(window.__BOOKS=window.__BOOKS||{})["e_rhesus"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Хор — троянская стража</span>"],["person","<span class=\"pn\">Корифей — старый воин</span>"],["person","<span class=\"pn\">Гектор, царь, предводитель троянской и союзной рати</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Эней — троянский вельможа</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Долон — троянец</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Пастух — старик</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"res\">Рес</span> — молодой фракийский царь</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"odissey\">Одиссей</span> |</span>"],["person","<span class=\"pn\">Диомед |</span>"],["person","<span class=\"pn\">Афина</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Парис</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Возница <span class=\"ch\" data-ch=\"res\">Реса</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Муза — мать <span class=\"ch\" data-ch=\"res\">Реса</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">} ахейские цари (II, III)</span>"],["place","Действие происходит в троянском лагере, на десятый год осады, ночью. Сцена представляет поле с шатром Гектора. Ночь. Вдали неясно мелькают огни. Хор подходит к палатке царя. Это вооруженные троянцы, в кольчугах и темных плащах."],["act","Действие первое","a1","I"],["scene","Явление первое","s1",1,1],["sp","Корифей"],["dir","к хору"],["v","Смена дежурная!",0,1,0,0],["v","Стражи товарищи!",0,1,0,0],["v","Полухор подходит.",0,1,0,0],["v","К <span class=\"ch\" data-ch=\"gektor\">Гектору</span> спящему",0,1,0,0],["v","Пусть кто-нибудь",0,1,0,0],["v","В царский шатер войдет!",0,2,0,0],["sp","Первое полухорие"],["dir","обращаясь к ставке <span class=\"ch\" data-ch=\"gektor\">Гектора</span>"],["v","Гектор, проснися, царь!",0,3,0,0],["v","Гектор, проснись, наш царь!",0,4,0,0],["v","Голову с листьев сухих подними,",0,5,0,0],["v","Облокотись и глаза открой,",0,6,0,0],["v","Страшен твой царский взор!..",0,7,0,0],["v","…Гектор, послушай нас,",0,8,0,0],["v","С ложа воспрянь;",0,9,0,0],["v","Вести-то, вести, царь!",0,10,0,1],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","из шатра"],["v","Свой или враг?",0,10,0,0],["v","Кто там? Пароль!",0,11,0,0],["v","Кто разбудил меня?",0,12,0,0],["v","Мраком ночным одет,",0,13,0,0],["v","Кто у шатра стоит?",0,14,0,0],["sp","Второе полухорие"],["v","Стража троянская.",0,15,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Шум почему?",0,15,0,0],["sp","Хор"],["v","Все слава богу, царь!",0,16,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Слава богам!",0,17,0,0],["v","Что ж напугало вас? Козни полнощные?",0,18,0,0],["v","Пост вы покинули, лагерь тревожите!",0,19,0,0],["v","Вооруженными здесь мы вкушаем сон.",0,20,0,1],["v","Разве не знаете?",0,21,0,0],["sd","(Выходит из шатра в оружии, но без шлема, курчавая большая голова, недовольный, разминаясь на ходу.)"],["sp","Первое полухорие"],["str","Строфа"],["v","Гектор, копье возьми;",0,22,0,0],["v","В лагерь к союзникам, царь, поспеши!",0,23,0,0],["v","Пусть окольчужатся, сон от очей стряхнут!",0,24,0,0],["v","Звать посылай друзей, войско сбирать вели,",0,25,0,0],["v","Живо коней уздать!",0,26,2,0],["v","Сына Панфоева с ложа поднять скажи,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,27,0,0],["v","Славной Европы сын",0,28,0,0],["v","Пусть нам бойцов ведет.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,29,2,0],["v","Надо гадателей — жертвы исследовать,",0,30,2,1],["v","Надо нам пращников,",0,31,2,0],["v","С крепкими луками",0,32,2,0],["v","Надо стрелков сюда!",0,33,2,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","И много слов, а не пойму…",0,34,0,0],["v","Разуверял, а тут путаешь!..",0,35,0,0],["v","Страж, если Пан тебя вконец",0,36,0,0],["v","Еще не сбил своим стрекалом,",0,37,0,0],["v","Скажи ясней, откуда страх?",0,40,0,1],["sp","Второе полухорие"],["str","Антистрофа"],["v","Целую ночь не спит",0,40,0,0],["v","Лагерь ахейский, царь, — всюду огни!",0,41,0,0],["v","Пламенем факелов вражьих судов ряды",0,42,0,0],["v","В мраке то здесь, то там ярко осветятся.",0,43,0,0],["v","К Агамемноновой",0,43,2,0],["v","<span class=\"ch\" data-ch=\"gektor\">Гектор</span> поднимает голову.",0,44,0,0],["v","Ставке вожди спешат с шумом, с тревогою:",0,45,0,0],["v","Будто приказа ждут",0,46,0,0],["v","Эллины царского.",0,46,2,0],["v","В страхе таком еще я не видал их, царь.",0,47,2,0],["v","<span class=\"ch\" data-ch=\"gektor\">Гектор</span> берет копье от оруженосца.",0,48,0,0],["v","Надо заранее",0,49,0,0],["v","Было сказать тебе:",0,50,0,1],["v","Как я спешил сюда!..",0,50,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","на минуту обращаясь к хору, потом приковывается взглядом к мерцающим вдали огонькам"],["v","В час добрый, коли так!.. Я не сержусь",0,51,0,0],["v","За вести страшные. Я так и думал: греки",0,52,0,0],["v","Хотят налечь на весла и уплыть",0,53,0,0],["v","От наших стен, ночною мглой прикрывшись.",0,54,0,0],["sd","(Всматривается в даль.)"],["v","Да, вот оно, огней сигнальных пламя!",0,55,0,0],["v","Отрадный блеск!.. Ты не хотел, Арей,",0,56,0,0],["v","Чтоб лев счастливым ловом насладился,",0,57,0,0],["v","Ты не хотел, чтоб от ахейских сил",0,58,0,0],["v","Моя рука оставила лишь тени.",0,59,0,0],["sd","(Продолжая смотреть в даль, судорожно сжимает древко копья.)"],["v","Да, если бы над головой у нас",0,60,1,1],["v","Теперь лучи горели солнца, знайте:",0,60,0,0],["v","Я бы копья не выпустил из рук,",0,61,0,0],["v","Пока б огонь не истребил их флота,",0,62,0,0],["v","Пока б моя убийственная длань",0,62,0,0],["v","Среди шатров вождей не уложила.",0,63,0,0],["v","О, я готов и ночью воевать,",0,64,0,0],["v","Да вещие гадатели решили",0,64,0,0],["v","Вслед за богами, чтобы днем я шел:",0,65,0,0],["v","«Тогда, мол, греков всех ты переколешь».",0,66,0,0],["v","«Дождися света!» — говорить легко,",0,66,0,0],["v","А греки тоже будут дожидаться?.. (В волнении.)",0,67,0,0],["v","Бегут, бегут, и ночь их бережет.",0,68,0,0],["sd","(С загоревшимся взором.)"],["v","Нет, я не дам уплыть им! (Громко.)",0,68,0,0],["v","Бить тревогу!",0,69,2,0],["v","Всех на ноги! К оружию! И в бой!",0,70,0,1],["v","Нежданными мы кинемся на греков,",0,70,0,0],["v","Им на суда забраться не дадим…",0,71,0,0],["v","Пусть, кровью обливаясь, со ступеней",0,72,0,0],["v","На нашу землю хищники падут",0,73,0,0],["v","Или идут рабами в тяжких узах",0,74,0,0],["v","Распахивать фригийские поля…",0,75,0,0],["sp","Корифей"],["v","Царь, мы еще доподлинно не знаем,",0,76,0,0],["v","Бегут ли греки… Не спешишь ли ты?",0,77,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Как не бегут? А их огни, движенье?",0,78,0,0],["sp","Корифей"],["v","Не знаю, царь, но страх меня берет…",0,79,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Стыдись! Ты просто трусишь, караульный.",0,80,0,0],["sp","Корифей"],["v","Таких огней я точно не видал…",0,80,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","А их урон вчерашний помнишь, помнишь?",0,81,0,0],["sp","Корифей"],["v","Ты начал, царь, тебе же и решать!",0,82,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Перед врагом не речи нужны — копья.",0,83,0,0],["scene","Явление второе","s2",1,2],["v","Подходит Эней.",0,84,0,0],["sp","Корифей"],["v","Царь, кажется, Эней сюда спешит:<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,85,0,0],["v","Конечно, новости он важные имеет…",0,86,0,0],["sp","Эней"],["v","Что это значит, Гектор, у тебя",0,87,0,0],["v","Толпятся люди, речи говорятся?",0,88,0,0],["v","Тревогою объят твой царский стан…",0,89,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Бери копье, Эней, оденься в панцирь!",0,90,0,1],["sp","Эней"],["v","А что? Ты козни новые открыл?",0,91,0,0],["v","Засаду, что ль, готовят ночью греки?",0,92,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Всю ночь в их стане факелы и шум,",0,93,0,0],["v","Они не ждут до света — это ясно.",0,94,0,0],["v","На быстрых кораблях огни зажглись;",0,95,0,0],["v","Они бегут. Эней, ты видишь? видишь?",0,96,0,0],["sd","(Не отрываясь взглядом от тускло мигающих огней.)"],["sp","Эней"],["dir","отстраняясь"],["v","Но царь в оружии! Что ж замышляет он?",0,97,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Что замышляю? Шутишь ты, вельможный?",0,100,0,1],["v","Да не бежать же грекам из-под стен?",0,100,0,0],["v","Когда сам бог дает троянской рати",0,101,0,0],["v","Победу верную, позорно отпускать",0,102,0,0],["v","От этих стен ахейцев без расплаты,",0,103,0,0],["v","Свободу им, отчизну возвращать.",0,103,0,0],["sp","Эней"],["v","О, если бы и разум по отваге",0,104,0,0],["v","Тебе судили боги! То-то нет.",0,105,0,0],["v","Один и тот же человек не может",0,106,0,0],["v","Все совместить. Ты, Гектор, ты — герой,",0,106,0,0],["v","Муж битвы, славы, только не совета.",0,107,0,0],["v","Как? Оттого, что сторож увидал,",0,108,0,0],["v","Что факелы мелькают в стане греков,",0,109,0,0],["v","Ты бегству их поверил, ты готов",0,110,0,1],["v","Построить войско и через окопы",0,110,0,0],["v","Теперь же, ночью, двинуться к судам?",0,111,0,0],["v","Ну, хорошо, положим, что удастся",0,112,0,0],["v","Тебе глубокие окопы перейти…",0,113,0,0],["v","А если греки не бегут и встретят",0,113,0,0],["v","Тебя лицом к лицу, ну что тогда?",0,114,0,0],["v","Отрезанный от города, отбитый,",0,115,0,0],["v","Не мнишь ли даром, Гектор, миновать",0,116,0,0],["v","Их заграждения? Да на одних мостах",0,116,0,0],["v","Переломаете вы все свои колеса…",0,117,0,0],["v","А в случае победы, — неужели",0,118,0,0],["v","Ты думаешь, что Ахиллес отдаст",0,119,0,0],["v","Тебе суда спалить, что он потерпит,",0,120,0,1],["v","Чтоб в рабство ты ахейцев уводил?",0,120,0,0],["v","Дух пламенный в герое и отважный!",0,121,0,0],["v","Нет, Гектор, дай, склонившись на щиты,",0,122,0,0],["v","Солдатам отдохнуть от тяжкой брани;",0,123,0,0],["v","А лучше кликни-ка охотника в дозор,",0,124,0,0],["v","Пусть он к врагам украдкой проберется,",0,125,0,0],["v","И, если точно бегство решено,",0,126,0,0],["v","Напасть еще успеешь; если ж козни",0,127,0,0],["v","Готовятся троянцам в мраке ночи,",0,128,0,0],["v","Он все расскажет нам подробно, и тогда",0,129,0,0],["v","Посудим. Вот тебе совет Энея.",0,130,0,1],["sp","Первое полухорие"],["str","Строфа"],["v","Правду Эней сказал:",0,130,0,0],["v","Гектор, одумайся!",0,131,0,0],["v","Горе упорное",0,132,0,0],["v","Войску вожди несут.",0,133,0,0],["v","К грекам лазутчика",0,133,0,0],["v","Ты поскорей пошли:",0,134,0,0],["v","Пусть про огни тебе,",0,135,0,0],["v","Что на судах горят,",0,136,0,0],["v","Все он разведает.",0,136,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Вы порешили так, — и я не спорю.",0,137,0,0],["v","Поди же, успокой союзников, Эней!",0,138,0,0],["sd","(Прислушивается.)"],["v","Да, в лагере уж поднялась тревога…",0,139,0,0],["v","А я разведчика пошлю во вражий стан,",0,140,0,1],["v","И если весть он принесет о кознях,",0,140,0,0],["v","Я за тобой немедленно пошлю:",0,141,0,0],["v","Ты сам тогда дозорщика расспросишь…",0,142,0,0],["v","Но если точно их побег готов,",0,143,0,0],["v","Я трубачу играть велю; услышишь-",0,144,0,0],["v","Спеши сюда и знай, что царь не ждет,",0,145,0,0],["v","Знай, что до света у судов ахейских",0,145,0,0],["v","С бегущими вступает <span class=\"ch\" data-ch=\"gektor\">Гектор</span> в бой.",0,146,0,0],["sp","Эней"],["v","Ищи ж разведчика; теперь ты судишь здраво;",0,147,0,0],["v","Так верь, что труд с царем я разделю.",0,148,0,0],["sd","(Уходит.)"],["scene","Явление третье","s3",1,3],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Вы слышали, троянцы? Кто решится",0,149,0,0],["v","Сейчас тайком пробраться к грекам в стан?",0,150,0,1],["v","Кто справит службу трудную для Трои?",0,150,0,0],["v","Все стоят молча.",0,151,0,0],["v","Молчите вы? Иль должен я один",0,152,0,0],["v","Работать на союзников и Трою!..",0,153,0,0],["sp","Долон"],["dir","выступая из толпы троянцев"],["v","Царь! Я хочу родной земле служить.",0,154,0,0],["v","Лазутчиком метнусь я в лагерь греков, —",0,155,0,0],["v","Разведаю и вести принесу;",0,156,0,0],["v","Опасность велика, да что ж тут делать?",0,157,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Ты хочешь имя оправдать, Долон,<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,158,0,0],["v","Хитрец отважный? Так пускай же отчий",0,159,0,0],["v","Твой славный дом прославится вдвойне.",0,160,0,1],["sp","Долон"],["v","За этот труд и милостью, конечно,",0,161,0,0],["v","Меня ты не оставишь. Человек",0,162,0,0],["v","Всегда усердней, если ждет награды.",0,163,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Награды ли для смелого жалеть?",0,164,0,0],["v","Все дам тебе — оставь мне только царство.",0,165,0,0],["sp","Долон"],["v","Что в царстве? С ним забот хоть отбавляй.<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,166,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Я сделаю тебя, Долон мой, царским зятем..",0,167,0,0],["sp","Долон"],["v","Жену знатней себя… Ну, нет, уволь!<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,168,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Так золота в награду ты попросишь?",0,169,0,0],["sp","Долон"],["v","И тоже нет, своим я проживу.",0,170,0,1],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Что ж может дать тебе властитель Трои?",0,171,0,0],["sp","Долон"],["v","Пусть вспомнит нас, как греков победит.",0,172,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Добычу всю. Мне — только двух Атридов.",0,173,0,0],["sp","Долон"],["v","Убей их сам! На что мне Менелай?",0,174,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Ты, может быть, мечтаешь об Аяксе?",0,175,0,0],["sp","Долон"],["v","Нет, воин не научится пахать!",0,176,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Но за кого же выкуп взять ты хочешь?",0,177,0,0],["sp","Долон"],["v","Царь, я сказал тебе, что я богат…",0,178,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Доспехи с мертвых греков? Сам укажешь…",0,179,0,0],["sp","Долон"],["v","Ты в храме, Гектор, латы их повесь!",0,180,0,1],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Но, наконец, чего ж ты хочешь, воин?",0,180,0,0],["sp","Долон"],["v","Чего хочу? Царь <span class=\"ch\" data-ch=\"gektor\">Гектор</span>, обещай",0,181,0,0],["v","Долону колесницу Ахиллеса.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,182,0,0],["v","Ты скажешь, что награда велика;",0,183,0,0],["v","Но вспомни только: я рискую жизнью.",0,184,0,0],["v","Не пожалей Пелидовых коней.",0,185,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","помолчав"],["v","Коней Пелида…",0,185,0,0],["sd","(В раздумье.)"],["v","Я мечтал о них.",0,186,4,0],["v","Бессмертные, бессмертных порожденье,",0,187,0,0],["v","Ахилла ярого они, как вихорь, мчат…",0,188,0,0],["v","Молва идет, что сам владыка моря,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,189,0,0],["v","Объездив, их Пелею подарил.",0,190,0,1],["v","За дочерью их отдал брат Зевеса…",0,190,0,0],["v","Но отступать от слов царю — не след.",0,191,0,0],["sd","(Думает.)"],["v","Я дам тебе запряжку Ахиллеса:",0,191,0,0],["v","Ни у кого дороже вещи нет.",0,192,0,0],["v","Уходит в шатер.",0,192,0,0],["scene","Явление четвертое","s4",1,4],["v","Те же, без <span class=\"ch\" data-ch=\"gektor\">Гектора</span>.",0,193,0,0],["sp","Долон"],["v","Хвала тебе, царь <span class=\"ch\" data-ch=\"gektor\">Гектор</span>! Из фригийцев",0,193,0,0],["v","Я лучший дар за подвиг получу.",0,194,0,0],["v","Ты ж, доблестный, ты первый не завидуй,",0,194,0,0],["v","Ахейская добыча велика.",0,195,0,0],["sp","Второе полухорие"],["str","Антистрофа"],["v","Чудной наградою",0,195,0,0],["v","Дело великое,",0,196,0,0],["v","Громкою славою",0,196,0,0],["v","Подвиг венчается!",0,197,0,0],["v","Если ж подумаешь,",0,197,0,0],["v","Счастлив и царский зять…",0,198,0,0],["v","Жизнь ты на божий суд",0,198,0,0],["v","Отдал теперь, Долон…",0,199,0,0],["v","Люди не выручат.",0,200,0,1],["sp","Долон"],["v","Скорей, скорей в шатер! Я там займусь",0,201,0,0],["v","Своим нарядом. К кораблям ахейским",0,202,0,0],["v","Не так же мне, в оружии, идти!..",0,203,0,0],["sp","Хор"],["v","Переоденешься, Долон, ты для дозора?",0,204,0,0],["sp","Долон"],["v","Еще бы! И наряд давно готов.",0,205,0,0],["sp","Хор"],["v","Ну что ж, смельчак, тебе и книги в руки;",0,206,0,0],["v","А ты мне не опишешь свой наряд?",0,207,0,0],["sp","Долон"],["v","Я на плечи надену волчью шкуру,<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,208,0,0],["v","Под маской волка спрячу я лицо.",0,209,0,0],["v","У хищника походку переняв,",0,210,0,1],["v","Я побегу, как волк, на четвереньках.",0,210,0,0],["v","В личине этой возле кораблей",0,211,0,0],["v","Едва ли враг какой меня узнает…",0,212,0,0],["v","Ну, а дорогой, где людей не видно,",0,213,0,0],["v","На двух ногах, конечно, я пойду…",0,213,0,0],["v","Вот вам, друзья, вся выдумка Долона.",0,214,0,0],["sp","Корифей"],["v","Ну, в добрый час, Долон, и пусть Гермес,",0,215,0,0],["v","Бог хитростей, тебя обратно в лагерь",0,216,0,0],["v","Доставит. Выдумка, конечно, хороша,",0,216,0,0],["v","Да выполнить ее нужна удача…",0,217,0,0],["sp","Долон"],["v","Удача будет. Солнце не взойдет,",0,218,0,0],["v","А я к тебе вернуся, невредимый,",0,219,0,0],["v","С добычей, да какой еще, гляди!",0,220,0,1],["v","И чтоб поверил ты, что у ахейцев",0,221,0,0],["v","Я был, Тидиду голову срублю<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,222,0,0],["v","Иль <span class=\"ch\" data-ch=\"odissey\">Одиссею</span> и рукой кровавой",0,223,0,0],["v","Ее троянцам брошу… до зари.",0,224,0,0],["scene","Первый музыкальный антракт","s5",1,5],["sp","Хор"],["str","Строфа I"],["v","Стены воздвигнувший Трои,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,225,0,0],["v","Дела владыка могучий,",0,226,2,0],["v","В Ликии чтимый, бог лучезарный,",0,227,0,0],["v","Молим тебя, Аполлон:",0,228,2,0],["v","В дни испытания нас не оставь ты!",0,230,0,1],["v","Смелому мужу хранителем будь",0,231,0,0],["v","В мраке полнощном!",0,232,2,0],["str","Антистрофа I"],["v","Дай ему силы добраться,",0,233,0,0],["v","В лагерь их вражий и в Трою",0,234,2,0],["v","К отчему дому дай воротиться!",0,235,0,0],["v","После ж, когда Приамид",0,236,2,0],["v","Ярое войско Атридов рассеет,",0,237,0,0],["v","Бешеной дай насладиться ездой",0,240,0,1],["v","Веном Пелея!",0,241,2,0],["str","Строфа II"],["v","Сколько сынов у Трои,",0,242,0,0],["v","Только один решился",0,243,2,0],["v","В лагерь врагов пробраться.",0,244,2,0],["v","В час, когда волны темнеют,",0,245,0,0],["v","Мало в ней крепких духом…",0,246,0,0],["v","Нет, унывать не надо!",0,247,2,0],["v","Смелые есть и в Трое…",0,250,2,1],["v","Дружбу детей Приама",0,251,2,0],["v","Кто, безумец, отвергнет?",0,252,2,0],["str","Антистрофа II"],["v","Голову чью Долон нам,",0,253,0,0],["v","Волк принесет двуногий?",0,254,2,0],["v","Грека сулил убить он…",0,255,2,0],["v","Пусть обезглавит Спартанца",0,256,0,0],["v","Или другого Атрида…<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,257,0,0],["v","С воплями пусть Елена",0,260,2,1],["v","Голову зятя примет!",0,260,2,0],["v","Войска привез немало",0,261,2,0],["v","В Трою владыка греков.",0,262,2,0],["act","Действие второе","a2","II"],["scene","Явление пятое","s6",2,6],["sd","<span class=\"ch\" data-ch=\"gektor\">Гектор</span> и вестник. (Вестник — старый пастух: овчина на плечах, седеющие волосы, лоб в морщинах, толстый нос, в руках палка.)"],["sp","Пастух"],["dir","приближается к шатру"],["v","О, господин! Пусть боги мне дадут",0,263,0,0],["v","Всегда царям носить такие вести.",0,264,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Ох эти пастухи! Вот выбрал час",0,265,0,0],["v","Порадовать своей пастушьей вестью",0,265,0,0],["v","Вооруженный лагерь. Проходи:",0,266,0,0],["v","Ты, право, не туда зашел, приятель.",0,267,0,0],["v","Дворец отца и мой троянский дом",0,268,0,0],["v","Тебе знакомы, ну и отправляйся",0,269,0,0],["v","Рабам рассказывать об овцах и быках.",0,270,0,1],["sp","Пастух"],["v","Да, я — простой пастух, не знатный воин,",0,271,0,0],["v","Но вести добрые я <span class=\"ch\" data-ch=\"gektor\">Гектору</span> принес.",0,272,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Оставь, пастух. Какая весть из стойла?",0,273,0,0],["v","Мы битвы ждем, мы копья припасли.",0,274,0,0],["sp","Пастух"],["v","И мой рассказ к тому же приведется,",0,275,0,0],["v","Владыка <span class=\"ch\" data-ch=\"gektor\">Гектор</span>. Друг сюда идет,",0,276,0,0],["v","Союзник и с бессчетною дружиной!",0,277,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Откуда родом? из какой земли?",0,278,0,0],["sp","Пастух"],["v","Из Фракии, владыка, — сын Стримона.",0,279,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Ты говоришь о <span class=\"ch\" data-ch=\"res\">Ресе</span> нам, пастух?",0,280,0,1],["sp","Пастух"],["v","Царь угадал, и я не повторяю.",0,280,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Но дебри Иды разве путь ему?",0,281,0,0],["v","Для колесниц куда пригодней поле.",0,282,0,0],["sp","Пастух"],["v","Ну, этого тебе не объясню.",0,283,0,0],["v","Вот разве то подумаешь, что в поле",0,283,0,0],["v","Не так-то безопасно по ночам:",0,284,0,0],["v","Враги — кругом. В лесу-то поспокойней.",0,285,0,0],["v","Мы с склонов Иды родом будем, царь,",0,286,0,0],["v","Откуда и твои троянцы вышли.",0,286,0,0],["v","Вот под вечер пасем себе стада, —",0,287,0,0],["v","Вдруг из лесу несется необычный",0,288,0,0],["v","И страшный шум: не ветер и не зверь.",0,289,0,0],["v","А следом, как поток, на нас солдаты.",0,290,0,1],["v","И страху же тогда мы набрались…",0,291,0,0],["v","\"Ну, — думаем, — пропасть скоту! Ахейцы",0,292,0,0],["v","Не пожалеют царского добра —",0,293,0,0],["v","Скорее в горы!\" Слышим, — нет, не греки",0,294,0,0],["v","По говору, — от сердца отлегло;",0,295,0,0],["v","Дозорщиков я отличил тут царских",0,296,0,0],["v","И по-фракийски речь к ним обратил:",0,297,0,0],["v","\"Скажите, люди, чья это дружина,",0,298,0,0],["v","Чей сын идет троянцев выручать?\"",0,299,0,0],["v","«<span class=\"ch\" data-ch=\"res\">Рес</span>», — говорят, и вдруг передо мною",0,300,0,1],["v","Сам <span class=\"ch\" data-ch=\"res\">Рес</span> на колеснице, точно бог:",0,301,0,0],["v","Белее снега лошади, на шее",0,302,0,0],["v","Ярмо у них все золотом горит,",0,303,0,0],["v","А у царя у самого сияет",0,304,0,0],["v","На плечах золотой узорный щит.",0,305,0,0],["v","Над гривами у кобылиц из меди",0,306,0,0],["v","Горгона страшная, вся в бубенцах, гремит…",0,307,0,0],["v","А что солдат у <span class=\"ch\" data-ch=\"res\">Реса</span>, — сметы нету:",0,308,0,0],["v","И всадники, и плотные ряды",0,310,0,1],["v","Пельтастов, а стрелков-то, Гектор, сколько,<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,311,0,0],["v","И сколько в лисьих шкурах с ним людей…",0,312,0,0],["v","Так вот какой идет союзник в Трою.",0,313,0,0],["v","Пусть с ним Пелид сразится иль бежит;",0,314,0,0],["v","Не думаю, чтоб он в живых остался…",0,315,0,0],["sp","Корифей"],["v","Уж если боги к людям хороши,",0,316,0,0],["v","Все будет им ручить и удаваться.",0,317,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","О да, теперь, когда мое копье",0,318,0,0],["v","Венчалось славой и Кронид за Трою, —",0,320,0,1],["v","Друзей, конечно, много я найду.",0,320,0,0],["v","Их помощи не нужно мне! Что раньше,",0,321,0,0],["v","Когда Арей свирепый нас громил,",0,322,0,0],["v","Страданий и трудов не приходили",0,323,0,0],["v","С троянцами делить? Нам <span class=\"ch\" data-ch=\"res\">Рес</span> — не друг:",0,324,0,0],["v","Торопится он к пиру после лова;",0,325,0,0],["v","А что же к лову он не поспешал,",0,325,0,0],["v","Что он в бою копьем не выручал нас?",0,326,0,0],["sp","Корифей"],["v","Друзья такие плохи, спору нет,",0,327,0,0],["v","А все же помощь — делу не помеха.",0,328,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","На страже <span class=\"ch\" data-ch=\"gektor\">Гектор</span>. Троя может спать.",0,329,0,0],["sp","Корифей"],["v","Ну, а враги разбиты, — ты уверен?",0,330,0,1],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","И ты уверишься, когда дождемся дня!",0,331,0,0],["sp","Корифей"],["v","Эй, Гектор, вспомни: счастье переменно.",0,332,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Давно бы в Трое был хороший друг…",0,333,0,1],["v","А этот <span class=\"ch\" data-ch=\"res\">Рес</span>… Он будет принят с честью,",0,336,0,1],["v","Как знатный гость, но не союзник, нет!",0,336,0,0],["v","Мы угостим его за царскою трапезой,",0,337,0,0],["v","Но благодарности Приама <span class=\"ch\" data-ch=\"res\">Рес</span>",0,337,0,0],["v","Уж заслужить не может… Слишком поздно.",0,338,0,1],["sp","Корифей"],["v","А не зазорно помощь отвергать?",0,334,0,1],["sp","Пастух"],["v","Хоть покажи его аргосцам, <span class=\"ch\" data-ch=\"gektor\">Гектор</span>:",0,335,0,0],["v","Он ужасом наполнит вражий стан.",0,336,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","подумав"],["v","В твоих словах, пастух, есть доля правды.",0,339,0,1],["sd","(К слугам.)"],["v","Пусть к нам войдет раззолоченный <span class=\"ch\" data-ch=\"res\">Рес</span>,",0,340,0,1],["v","Который ищет с Троей быть в союзе.",0,341,0,0],["scene","Второй музыкальный антракт","s7",2,7],["sp","Хор"],["str","Строфа I"],["v","Зевсова дочь, Неизбежная<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,342,0,0],["v","Дева, тебе я молюсь:",0,343,0,0],["v","Дай мне сказать, чем душа полна, —",0,344,0,0],["v","Зависть богов удали!",0,345,0,0],["v","Здесь ты, потока фракийского,",0,346,0,0],["v","Здесь ты, прославленный сын!",0,347,0,0],["v","Муза, героя родившая,",0,348,0,0],["v","Стримон отец снарядил.",0,350,0,1],["str","Антистрофа I"],["v","Стримон волну свою бурную",0,350,0,0],["v","В чистое лоно излил,",0,351,0,0],["v","И от волны родила",0,352,0,0],["v","Муза тебя сладкозвучная…",0,353,0,0],["v","Блеск ты похитил у молнии,",0,354,0,0],["v","Ветер несет кобылиц…",0,355,0,0],["v","Фригия, милая родина,",0,356,0,0],["v","Ты спасена, спасена!",0,357,0,0],["str","Строфа II"],["v","Троя, древняя столица,",0,358,0,0],["v","Доведется ли тебе",0,359,0,0],["v","Снова видеть хороводы",0,360,0,0],["v","И любви веселый праздник,",0,361,0,0],["v","Где хмельная чаша ходит",0,362,0,0],["v","По рукам, да в круговеньку,",0,363,0,0],["v","Среди песен, среди смеха…",0,364,0,0],["v","А Атриды, немилые гости,",0,365,0,0],["v","Уплывут ли из Трои в отчизну?",0,366,0,0],["v","Пусть же боги тогда и фракийца,",0,367,0,0],["v","Что копьем отбивать нас пришел,",0,368,0,0],["v","К очагу приведут невозбранно.",0,369,0,0],["str","Антистрофа II"],["v","Покажись же, гость фракийский,",0,370,0,1],["v","Ждем тебя мы, славный <span class=\"ch\" data-ch=\"res\">Рес</span>!",0,370,0,0],["v","Царь, когда перед Пелидом",0,371,0,0],["v","Ты предстанешь, щит злаченый",0,372,0,0],["v","Наклоняя, заслонися,",0,373,0,0],["v","Разъяри кобыл сначала,",0,374,0,0],["v","А потом метнешь и дротик.",0,375,0,0],["v","Если ж дерзкий кто биться захочет, —",0,375,0,0],["v","Милый Аргос на празднике Геры",0,376,0,0],["v","Не видать ему с пляской священной:",0,377,0,0],["v","От руки фракийской падет",0,378,0,0],["v","На поля наши бременем сладким…",0,379,0,0],["act","Действие третье","a3","III"],["scene","Явление шестое","s8",3,8],["sd","Показывается <span class=\"ch\" data-ch=\"res\">Рес</span>; блестящая кольчуга прикрыта коротким пурпурным плащом, шлем горит позолотой; большой щит, гремя, висит за спиной; в руках копье. Он золотистый блондин и гораздо моложе <span class=\"ch\" data-ch=\"gektor\">Гектора</span>."],["sp","Хор"],["dir","при входе <span class=\"ch\" data-ch=\"res\">Реса</span>"],["v","Вот он!..",0,380,2,1],["v","Вот он, великий, желанный…",0,380,0,0],["v","Слава, слава тебе!",0,381,2,0],["v","Львенком ты вырос в горах…",0,381,0,0],["v","Боги, какой он красивый,",0,382,0,0],["v","Вот уж поистине — царь!",0,382,0,0],["v","Золота, золота сколько:",0,383,0,0],["v","Так в темноте и горит;",0,384,0,0],["v","Звон от злаченых доспехов",0,384,0,0],["v","В воздухе так и стоит.",0,385,0,0],["v","Бога узрела ты, Троя!",0,385,0,0],["v","Да, это — бог!",0,386,2,0],["v","Стримона сын и Музы певучей",0,387,0,0],["v","Силы в троянцев вдохнет.",0,387,2,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["dir","приближается к <span class=\"ch\" data-ch=\"gektor\">Гектору</span> с почтительным и радостным приветом"],["v","Привет тебе, троянский властелин,",0,388,0,0],["v","Могучий сын великого Приама!",0,388,0,0],["v","О Гектор! Наконец-то говорить",0,389,0,0],["v","Нам довелось, и вновь тебя я вижу…",0,390,0,1],["v","Ты к лагерю аргосскому подвел",0,390,0,0],["v","Свои войска. Я рад твоей удаче.",0,391,0,0],["v","Не правда ли, что вместе мы теперь",0,392,0,0],["v","Разрушим стены и спалим их лодки?",0,393,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","мрачно"],["v","Сын Музы сладкозвучной, по отцу",0,393,0,0],["v","Стримона сын, уж не взыщи на слове!",0,394,0,0],["v","Я — человек прямой и говорю",0,395,0,0],["v","Всегда что думаю. Мы очень долго",0,396,0,0],["v","Вас ждали здесь, и другу уж давно",0,396,0,0],["v","Прийти бы надо было к изнемогшей",0,397,0,0],["v","Приамовой столице, не давать",0,398,0,0],["v","Аргосцам нас измучить. Ты не скажешь,",0,399,0,0],["v","Что зова ждал, чтоб привести солдат!",0,400,0,1],["v","Уж мы ль к тебе гонцов не отряжали,",0,400,0,0],["v","Послов не засылали, мы ль даров",0,401,0,0],["v","Тебе жалели, Рес? И все напрасно.",0,402,0,0],["v","Ты, варвар сам, нас, варваров, предать<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,403,0,0],["v","Не постыдился: «Тешьтесь, мол, ахейцы».",0,404,0,0],["v","Ты позабыл, что этою рукой",0,405,0,0],["v","И этот <span class=\"ch\" data-ch=\"gektor\">Гектор</span> из князьков ничтожных",0,405,0,0],["v","Тебя возвел в фракийские цари.",0,406,0,0],["sd","(Воодушевляясь.)"],["v","Как лев, тогда, ты помнишь, у Пангея",0,407,0,0],["v","Без устали врагов я сокрушал,<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,408,0,0],["v","В лицо рубил вельможных, не робея,",0,409,0,0],["v","Иль в рабство их тебе же отдавал,",0,410,0,1],["v","А память, благодарность где, фракиец?",0,410,0,0],["v","Ты растоптал ее. Ты в тягостные дни",0,411,0,0],["v","Троянцам долг платить не торопился…",0,412,0,0],["v","Чужие Трое люди столько лет",0,413,0,0],["v","Страдают здесь, иные в битве пали —",0,413,0,0],["v","Залогом верности они в могилах спят,",0,414,0,0],["v","Другие рядом с нами, в тяжких латах,",0,415,0,0],["v","Иль с быстрой колесницы бой ведут",0,416,0,0],["v","И холод и палящий зной — все терпят.",0,416,0,0],["sd","(С насмешкой смотря на него.)"],["v","А ты небось с подушек не сходил,",0,417,0,0],["v","Не отрывал от губ веселья чаши?",0,418,0,0],["v","Нет, царь, меня словами не купить.",0,419,0,0],["v","Ты встрече рад, — я тоже рад, что <span class=\"ch\" data-ch=\"res\">Ресу</span>",0,420,0,1],["v","Я слово горькое в глаза сказать могу.",0,420,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Ну, право же, у нас один характер!",0,421,0,0],["v","И говорить и действовать люблю",0,422,0,0],["v","Я напрямик, как ты, могучий <span class=\"ch\" data-ch=\"gektor\">Гектор</span>!",0,423,0,0],["v","«<span class=\"ch\" data-ch=\"res\">Рес</span> виноват». Да <span class=\"ch\" data-ch=\"res\">Ресу</span>, может быть,",0,424,0,0],["v","Печаль и гнев сильней терзали сердце,",0,425,0,0],["v","Чем <span class=\"ch\" data-ch=\"gektor\">Гектору</span>, когда мы были врозь.",0,425,0,0],["v","Все было у меня готово, только в Трою",0,426,0,0],["v","Солдат вести. И вдруг на нас войной",0,427,0,0],["v","Соседи, скифы. Вместо Трои к морю<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,428,0,0],["v","Евксинскому идти пришлось. Резня",0,429,0,0],["v","Упорная была там. Кровью скифов",0,430,0,1],["v","Упились наши копья, но людей",0,430,0,0],["sd","(понизив голос, печально)"],["v","И мы там, Гектор, много потеряли.",0,431,0,0],["v","Вот отчего тогда на помощь к вам",0,432,0,0],["v","Я не пришел. Ну, а теперь мы скифов",0,433,0,0],["v","Рассеяли, их дети у меня",0,433,0,0],["v","В заложниках, отцов же присмиревших",0,434,0,0],["v","Я данью обложил, и снова в путь,",0,435,0,0],["v","Без отдыха, от скифа да на грека.",0,436,0,0],["v","Заметь: водою только чрез пролив,<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,436,0,0],["v","Все сухопутьем… О, не думай, Гектор,",0,437,0,0],["v","Ни раззолоченной палаты, ни пиров,",0,438,0,0],["v","Я ложа мягкого… я сна не знал в походе.",0,439,0,0],["v","Меня фракийский ветер леденил,",0,440,0,1],["v","И этот плащ был все мое спасенье",0,440,0,0],["v","От холода. Я опоздал прийти,",0,441,0,0],["v","Ты говоришь. Уж будто не найдется",0,441,0,0],["v","У вас работы больше для копья?",0,442,0,0],["v","День изо дня ты десять лет воюешь,",0,443,0,0],["v","А до сих пор судьбой не решено,",0,443,0,0],["v","Кто победит. Дай только день мне, Гектор,",0,444,0,0],["v","Мне надо только день, и я прорву",0,445,0,0],["v","Окопы греков. Я ахейцев этих,",0,445,0,0],["v","Весь лагерь их прибрежный размечу.",0,446,0,0],["v","День подвигов и крови, — а назавтра",0,446,0,0],["v","Всем испытаньям <span class=\"ch\" data-ch=\"gektor\">Гектора</span> конец!",0,447,0,0],["v","У вас я не промедлю, — но покуда",0,448,0,0],["v","Дай мне натешиться кровавою игрой:",0,448,0,0],["v","Пусть завтра, Гектор, ни один троянец",0,449,0,0],["v","Не ополчается, и если суждено",0,450,0,1],["v","Мне быть последним, пусть копье фракийца",0,450,0,0],["v","Следы ахейские последние сметет.",0,451,0,0],["sp","Хор"],["v","Слава тебе!",0,452,2,0],["v","Сладкие речи!<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,453,2,0],["v","Зевс возлюбил тебя,",0,454,2,0],["v","Славный фракиец!",0,455,2,0],["v","Только от слов твоих,",0,456,2,0],["v","Вышнего молим,",0,457,2,0],["v","Зависти бледной",0,458,2,0],["v","Горькие стрелы",0,459,2,0],["v","Пусть удалит!",0,460,2,1],["v","Много у греков сильных,",0,460,0,0],["v","Но на судах аргосских",0,461,0,0],["v","Не было равного <span class=\"ch\" data-ch=\"res\">Ресу</span>,",0,461,0,0],["v","Нет и, верно, не будет!",0,462,0,0],["v","Не удержаться Аяксу,",0,463,0,0],["v","Если метнет он дротик,",0,463,0,0],["v","Не устоять и Пелиду…",0,464,0,0],["v","Вышние, дайте мне видеть",0,465,0,0],["v","День расплаты за Трою,",0,465,0,0],["v","Страшный удар его видеть!",0,466,0,0],["v","Дайте, молю вас, о боги!",0,466,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Да, Гектор, хоть не скоро, но по-царски",0,467,0,0],["v","Я расплачусь, а боги мне теперь",0,468,0,0],["v","Пусть не завидуют. Когда от греков Трою",0,468,0,0],["v","Я вызволю и для богов дары",0,469,0,0],["v","Ты отберешь от эллинской добычи,",0,470,0,1],["v","Тогда с тобою в дальний Аргос, царь,",0,470,0,0],["v","Мы двинемся. Задумал я Элладу",0,471,0,0],["v","Всю разорить копьем: они должны",0,472,0,0],["v","Страдания троянские изведать.",0,473,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","О Рес! Пусть боги только возвратят",0,474,0,0],["v","Спокойствие в измученную Трою,",0,475,0,0],["v","Осаду снимут только, и воздам",0,476,0,0],["v","Я славу им… А разорить Элладу",0,477,0,0],["v","Фракийцам не под силу будет, царь!",0,478,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Но здесь ведь цвет Эллады, царь, не так ли?",0,479,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","раздумчиво"],["v","Да, силу греков, Рес, я испытал.",0,480,0,1],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Мы их убьем… Какая ж трудность дальше?",0,480,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Не вдаль, ты лучше под ноги смотри.",0,481,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Царь, видно, мести предпочел терпенье.",0,482,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Довольно, <span class=\"ch\" data-ch=\"res\">Рес</span>. Да, я — троянский царь,",0,482,0,0],["v","И царства моего с меня довольно…",0,483,0,0],["v","Располагайся с войском — я даю",0,484,0,0],["v","Тебе свободу полную: на правом",0,485,0,0],["v","Или на левом фланге или в центре,",0,485,0,0],["v","Где выберешь, там щит свой и поставь.",0,486,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["dir","нетерпеливо"],["v","Один хочу я биться против греков;",0,487,0,0],["v","Пойми меня, один! Но если царь,",0,487,0,0],["v","Трудившийся так долго и упорно,",0,488,0,0],["v","Не хочет <span class=\"ch\" data-ch=\"res\">Ресу</span> чести уступить",0,489,0,0],["v","Сжечь вражий стан, пусть даст по крайней мере",0,490,0,1],["v","Мне с Ахиллесом драться, пусть поставит",0,490,0,0],["v","Меня в челе прославленных дружин.",0,491,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Нет, Рес, копья ты не метнешь в Ахилла…",0,492,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Среди врагов Пелида, значит, нет?",0,493,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","И посейчас в шатре, да не выходит:",0,494,0,0],["v","Разгневался на греческих вождей.",0,495,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","А, кроме Ахиллеса, есть герои?",0,495,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","По-моему, фракиец, ни Аякс,",0,496,0,0],["v","Ни Диомед Ахиллу не уступят.",0,497,0,0],["v","Ну, а по хитрости иль по речам,",0,498,0,0],["v","Так <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> взять. Да и храбрец же!",0,499,0,0],["v","Грек ни один троянцам столько горя<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,500,0,1],["v","Не причинил, как этот <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>.",0,500,0,0],["v","Раз ночью он забрался в храм Афины,",0,501,0,0],["v","Похитил идола и в вражий стан унес.",0,501,0,0],["v","А то, мошенник, нищим нарядился",0,502,0,0],["v","И за ограду наших стен проник;",0,503,0,0],["v","Лазутчиком его послали греки.",0,503,0,0],["v","Как эллинов он здесь у нас честил,",0,504,0,0],["v","Какие слал проклятья им! И что же?",0,505,0,0],["v","Всю стражу напоследок перерезал,",0,505,0,0],["v","Привратников убил — и скрылся в лагерь!",0,506,0,0],["v","И вечно-то он козни мастерит!",0,506,0,0],["v","А становище <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> будет",0,507,0,0],["v","Недалеко от Трои, где алтарь<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,508,0,0],["v","Фимбрейскому воздвигнут Аполлону…",0,508,0,0],["v","Да, с этим наслищем бороться нелегко…<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,509,0,0],["sp","<span class=\"ch\" data-ch=\"res\">Рес</span>"],["v","Царь, настоящий воин не захочет",0,510,0,1],["v","Тайком убить врага, — открыто он",0,510,0,0],["v","Пойдет. А этот вор, что притаился",0,511,0,0],["v","В своем гнезде и козни мастерит, —",0,512,0,0],["v","Я захвачу его живьем и, проколовши",0,513,0,0],["v","Насквозь, прибью к воротам городским;",0,514,0,0],["v","Пусть коршуны там пир себе устроят…",0,515,0,0],["v","Грабитель он, он — гнусный святотат",0,516,0,0],["v","И, право, лучшей смерти не достоин.",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Однако ночь еще… И отдохнуть",0,518,0,0],["v","Не лишнее… Пойдем, — тебе я место",0,519,0,0],["v","Вне лагеря троянцев укажу:",0,520,0,1],["v","Располагайся там, да помни лозунг",0,520,0,0],["v","«Феб-Аполлон». Смотри же, не забудь",0,521,0,0],["v","Солдатам передать его!",0,522,0,0],["sd","(Хору.)"],["v","Ступайте",0,522,4,0],["v","На аванпосты караулить. Да не спать!",0,523,0,0],["v","Вы встретите Долона. Если только",0,524,0,0],["v","Он жив, то скоро будет здесь.",0,525,0,0],["sd","Уходят."],["scene","Третий музыкальный антракт","s9",3,9],["v","Парастат 1-й",0,525,0,0],["v","Пятую смену",0,526,0,0],["v","Надо будить.",0,527,0,0],["sp","Первое полухорие"],["str","Строфа I"],["v","Одна за другою",0,527,2,0],["v","Полнощные звезды",0,528,0,0],["v","В эфире погасли,",0,529,0,0],["v","И только седьмица скитальцев<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,530,0,1],["v","Во мгле предрассветной горит",0,530,0,0],["v","Да в небе орел лучезарный",0,531,0,0],["v","Над лагерем спящим парит.",0,532,0,0],["v","Парастат 1-й",0,532,0,0],["v","Стражи, проснитесь!",0,533,0,0],["v","Воины, встаньте:",0,534,0,0],["v","Время сменять караулы!",0,534,0,0],["v","Видите: месяц бледнеет,",0,535,0,0],["v","Ранние звезды зажглись.",0,536,0,1],["v","Парастат 2-й",0,537,0,0],["sd","Антистрофа I 546 Тише, солдаты! Там — соловей."],["sp","Второе полухорие"],["v","О, сладкие звуки:",0,538,2,0],["v","Рыданья и трели",0,539,0,0],["v","С прибрежья несутся…",0,540,0,0],["v","Он ночью в гнезде разоренном,",0,550,0,1],["v","О сыне тоскуя, поет…<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,550,0,0],["v","Чу… вот и стада пробудились,",0,551,0,0],["v","И в горы свирель их зовет.",0,551,0,0],["v","Парастат 2-й",0,552,0,0],["v","Тяжкие веки",0,552,0,0],["v","Не разведу я:",0,553,0,0],["v","Сна не могу победить;",0,553,0,0],["v","Сладкая клонит дремота",0,554,0,0],["v","Перед румяной зарей.",0,555,0,1],["v","Парастат 1-й",0,552,0,0],["sd","Строфа II 537 В эту ночь кто был первым?"],["sp","Первое полухорие"],["v","Сын Мигдона, Кореб.",0,548,0,0],["v","Парастат 1-й",0,544,0,0],["v","А за ним?",0,540,0,1],["sp","Первое полухорие"],["sd","Киликийцы."],["v","[Парастат 1-й",0,540,0,0],["v","А потом?",0,541,0,0],["sp","Первое полухорие"],["v","Македонец.]",1,541,0,0],["v","Парастат 1-й",0,542,0,0],["v","А кто нас разбудил?",0,542,0,0],["sp","Первое полухорие"],["v","Мисийцы.",1,542,0,0],["v","Парастат 1-й<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,543,0,0],["v","А теперь чей черед?",0,544,0,0],["v","Кто дежурить идет?",0,545,0,1],["sp","Первое полухорие"],["v","Ликийцы.",1,545,0,0],["sp","Второе полухорие"],["v",". . . . . . . . . . . .",0,546,0,0],["v","Парастат 2-й",0,547,0,0],["sd","Антистрофа II 556 А Долон?"],["sp","Второе полухорие"],["sd","Не вернулся."],["v","Парастат 2-й",0,548,0,0],["v","Страх берет за него.",0,549,0,0],["sp","Второе полухорие"],["v","Не в засаду ли смелый",0,560,0,1],["v","Наш дозорщик попался?",0,560,0,0],["v","Парастат 2-й",0,561,0,0],["v","Не убитый ли спит",0,562,0,0],["v","В их стане?",0,563,0,0],["v","А теперь чей черед?",0,563,0,0],["v","Кто дежурить идет?",0,564,0,0],["sp","Второе полухорие"],["v","Ликийцы.",0,565,0,0],["act","Действие четвертое","a4","IV"],["scene","Явление седьмое","s10",4,10],["sd","Входят Диомед и <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>, без щитов; они прячут обнаженные мечи под плащами, говорят вполголоса, идут осторожно, крадучись."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ослышался я, что ли? Где-то точно",0,566,0,0],["v","Оружие бряцает? Чу!.. опять!",0,566,0,0],["sp","Диомед"],["v","Нет, это — упряжь, <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>; сначала",0,567,0,0],["v","Почудилось мне тоже, что народ",0,568,0,0],["v","Здесь ходит; это просто кони, сбруя.",0,569,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Потише… нет ли близко сторожей?",0,570,0,1],["sp","Диомед"],["v","И то смотрю… И темень же какая!",0,570,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Пароль-то знаешь ли на случай, Диомед?",0,571,0,0],["sp","Диомед"],["v","Долон сказал: пароль их — имя Феба.",0,572,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","подходит к шатру"],["v","Ба! Это что такое? Посмотри!",0,573,0,0],["v","В шатре-то никого. А где же <span class=\"ch\" data-ch=\"gektor\">Гектор</span>?",0,574,0,0],["sp","Диомед"],["v","Да, это царская стоянка: так Долон",0,575,0,0],["v","Нам говорил, и здесь проводит ночи",0,575,0,0],["v","Упрямый враг ахейцев Приамид.",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Что ж это значит? Нет ли где засады?",0,577,0,0],["sp","Диомед"],["v","Конечно, что-нибудь троянец мастерит…",0,578,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Да, он не трус, когда ему ручит.",0,579,0,0],["sp","Диомед"],["v","Так как же, Одиссей? Пропало дело?",0,580,0,1],["v","Мы спящего врага не порешим?",0,581,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Придется, видно, воротиться в лагерь…",0,582,0,0],["v","Что ж делать? Против бога не пойдешь,",0,583,0,0],["v","Коль Приамида взял он под защиту.",0,584,0,0],["sp","Диомед"],["v","А если бы нам грозному Энею",0,585,0,0],["v","Или Парису голову снести?",0,586,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","В такую темь где их искать по стану?",0,587,0,0],["v","И сам, пожалуй, с ними пропадешь.",0,588,0,0],["sp","Диомед"],["v","А лучше, что ль, с пустыми-то руками,",0,589,0,0],["v","Без славы воротиться к кораблям?",0,590,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Как так с пустыми? А Долон убитый?",0,590,0,0],["v","Лазутчика доспехи — наш трофей.",0,591,0,0],["v","Вот разохотился Тидид-то: целый лагерь",0,592,0,0],["v","Готов убить… Самим бы уцелеть.",0,593,0,0],["sd","(Спешат.)"],["scene","Явление восьмое","s11",4,11],["sp","Афина"],["dir","преграждая им путь"],["v","Остановитесь, греки… Неприлично",0,594,0,0],["v","В унынии стан вражий покидать.",0,595,0,0],["v","И что смутило вас? Что Александра<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,595,0,0],["v","Иль <span class=\"ch\" data-ch=\"gektor\">Гектора</span> вам не дал бог убить?",0,596,0,0],["v","Внемлите мне, герои: в этом стане",0,597,0,0],["v","Сегодня отдыхает новый гость,",0,598,0,0],["v","Могучий <span class=\"ch\" data-ch=\"res\">Рес</span>, фракийский повелитель.",0,599,0,0],["sd","(Внушительно и раздельно.)"],["v","Он этой ночью должен умереть…",0,600,0,1],["v","Смотрите: если только до рассвета",0,600,0,0],["v","Он доживет, наутро ни Аякс,",0,601,0,0],["v","Ни Ахиллес не оградят ваш лагерь;",0,602,0,0],["v","Фракиец стены ваши сокрушит,",0,603,0,0],["v","Себе копьем широкий путь проложит…",0,604,0,0],["v","Вы поняли меня? не о шатре,",0,605,0,0],["v","Не об убийстве <span class=\"ch\" data-ch=\"gektor\">Гектора</span> вам думать",0,606,0,0],["v","Теперь. Все это в очередь придет.",0,607,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Владычица! Божественным приветом",0,608,0,0],["v","Твой голос уху чуткому звучит:",0,609,0,0],["v","Ты в трудную минуту мне всегда",0,610,0,1],["v","Поможешь. Мы не знаем ставки <span class=\"ch\" data-ch=\"res\">Реса</span>;",0,610,0,0],["v","Конечно, здесь он, в стане, помещен?",0,611,0,0],["sp","Афина"],["v","Поблизости. Но только надо выйти",0,612,0,0],["v","Из лагеря. Царь <span class=\"ch\" data-ch=\"gektor\">Гектор</span> приказал,",0,613,0,0],["v","Чтоб света <span class=\"ch\" data-ch=\"res\">Рес</span> вне стана дожидался.",0,614,0,0],["v","Палатку <span class=\"ch\" data-ch=\"res\">Реса</span> вы узнаете сейчас",0,615,0,0],["v","По лошадям привязанным; их видно",0,615,0,0],["v","И в темноте: как крылья лебедей",0,616,0,0],["v","Над влагою речной, они белеют.",0,617,0,0],["v","Когда владельца их убьете, будет вам",0,618,0,0],["v","Запряжка эта доброю добычей.",0,619,0,0],["v","Едва ли есть в каком-нибудь краю",0,620,0,1],["v","Такие кобылицы, как у <span class=\"ch\" data-ch=\"res\">Реса</span>…",0,620,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Что ж, Диомед, ты <span class=\"ch\" data-ch=\"res\">Реса</span> порешишь?",0,621,0,0],["v","Нет, я убью! А ты кобыл захватишь…",0,622,0,0],["sp","Диомед"],["v","Уж лучше мне фракийца предоставь,",0,623,0,0],["v","А сам управься с Ресовой запряжкой:",0,624,0,0],["v","Как мастеру, могучий <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>,",0,625,0,0],["v","Тебе и дело надо потруднее.",0,626,0,0],["sp","Афина"],["v","Постойте, греки… К царскому шатру",0,627,0,0],["v","Парис идет… наверно, он прослышал",0,628,0,0],["v","От сторожей, что в лагере враги.",0,629,0,0],["sp","Диомед"],["v","Парис один, иль люди с ним, богиня?",0,630,0,1],["sp","Афина"],["v","Один… И направляется сюда,",0,630,0,0],["v","Чтоб объявить, что в стане есть лазутчик…",0,631,0,0],["v","Потише… вот он… брата не найдет…",0,632,0,0],["sp","Диомед"],["dir","шепотом"],["v","Убить его? Не правда ли, Афина?",0,633,0,0],["sp","Афина"],["v","Нет, Диомед, наперекор судьбе",0,633,0,0],["v","Идти не надо. Приамида скоро",0,634,0,0],["v","И без тебя убьют. На этот раз",0,635,0,0],["v","Тебя другая жертва ожидает,",0,636,0,0],["v","Не медли только… Я пока займу",0,636,0,0],["v","Париса разговором и Кипридой,",0,637,0,0],["v","Его заступницей, царевичу явлюсь.",0,638,0,0],["v","Не беспокойся, Диомед, про <span class=\"ch\" data-ch=\"res\">Реса</span>",0,639,0,0],["v","Троянец этот, хоть и близко был,",0,640,0,1],["v","Из наших уст понять не мог ни слова.",0,640,0,0],["v","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span> и Диомед уходят.",0,641,0,0],["scene","Явление девятое","s12",4,12],["sd","Парис, без шлема и оружия, небрежно одетый, подходит к царской ставке, потом Афина, принявшая вид Киприды."],["sp","Парис"],["dir","шепотом"],["v","Ты здесь ли, Гектор, царственный мой брат?",0,642,0,0],["v","Проснись скорей! Ахейцы — в нашем стане:",0,643,0,0],["v","Лазутчики иль воры — не понять…",0,644,0,0],["sp","Афина"],["v","Покинь свой страх, царевич! Я — Киприда,",0,645,0,0],["v","Моя рука всегда тебя хранит:",0,646,0,0],["v","Богиня чар любимого Париса",0,647,0,0],["v","За правый суд от копий защитит.<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,648,0,0],["v","Знай: завтра гость могучий и прекрасный",0,649,0,0],["v","Победою венчает Илион:",0,650,0,1],["v","Родился <span class=\"ch\" data-ch=\"res\">Рес</span> от Музы сладкогласной,",0,650,0,0],["v","И был отцом его поток Стримон.",0,651,0,0],["sp","Парис"],["v","О, благодатная! родную Трою",0,652,0,0],["v","И Александра лаской ты даришь!",0,653,0,0],["v","Сокровища нет выше этой ласки,",0,654,0,0],["v","И нет жены прекраснее тебя…",0,655,0,0],["v","Повсюду говор в лагере, богиня:",0,655,0,0],["v","Лазутчики пришли в троянский стан.",0,656,0,0],["v","Один слыхал, другой их даже видел:",0,657,0,0],["v","Из глаз пропали только у него…",0,658,0,0],["v","Я думал: пусть рассудит дело <span class=\"ch\" data-ch=\"gektor\">Гектор</span>,",0,659,0,0],["v","И поспешил прийти в его шатер.",0,660,0,1],["sp","Афина"],["v","Тревожиться не стоит. <span class=\"ch\" data-ch=\"gektor\">Гектор</span> вышел",0,661,0,0],["v","Дружину <span class=\"ch\" data-ch=\"res\">Реса</span> в поле разместить.",0,662,0,0],["sp","Парис"],["v","Благодарю тебя, богиня: ты Парису",0,663,0,0],["v","Вернула в душу мир. Я ухожу.",0,664,0,0],["sp","Афина"],["v","Прости, герой. Друзья Киприды будут",0,665,0,0],["v","В сраженьях побеждать. Увидишь сам.",0,666,0,0],["v","Парис уходит.",0,667,0,0],["scene","Явление десятое","s13",4,13],["sd","Входит <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> с мечом в крови, за сценой топот и ржанье лошадей."],["sp","Афина"],["dir","появляется в прежнем виде"],["v","А вы не горячитесь! Сын Лаэрта,",0,668,0,0],["v","Отточенный свой меч ты лучше спрячь.",0,669,0,0],["v","Спит на земле фракиец, ваша жертва,",0,670,0,1],["v","И кобылиц ему уж не отбить.",0,670,0,0],["v","Но не теряйте ни минуты: вести",0,671,0,0],["v","Уж носятся по стану, и на вас",0,672,0,0],["v","Гроза идет: домой, домой, герои!",0,673,0,0],["v","Вы слышите? Погоня, голоса…",0,673,0,0],["sp","Хор"],["dir","сначала за сценой"],["v","Ловите их, ловите их!",0,674,0,0],["v","Держи, держи!",0,675,2,0],["v","Коли его, руби его, коли его, коли его!",0,676,0,0],["sd","(Окружают и схватывают <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>.)"],["v","Так вот он,",0,676,2,0],["v","Разбойник.",0,677,2,0],["v","Весь лагерь",0,678,2,0],["v","Он поднял…",0,679,2,0],["v","Сюда скорей, ко мне скорей,",0,680,0,1],["v","Троянцы!",0,680,2,0],["v","Попался",0,681,2,0],["v","Лазутчик.",0,682,2,0],["v","Откуда ты —",0,682,2,0],["v","Какой земли?",0,683,2,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ловкий какой! Лучше оставь — сам пропадешь.",0,684,0,0],["sp","Первое полухорие"],["v","Ну, говори, что ли, пароль! Не то заколю…",0,685,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ах, погоди, не горячись!",0,685,0,0],["sp","Первое полухорие"],["v","Бейте его!",1,685,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","<span class=\"ch\" data-ch=\"res\">Реса</span> убить хочет злодей!",0,686,0,0],["sp","Первое полухорие"],["v","Вор — ты, не <span class=\"ch\" data-ch=\"res\">Рес</span>.",1,686,0,0],["sd","(Поднимают над ним ножи)."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Стойте вы там!",0,687,0,0],["sp","Первое полухорие"],["v","Бейте его!",1,687,0,0],["sp","Второе полухорие"],["v","Бей, коли враг.",1,687,0,0],["sp","Первое полухорие"],["v","Что же пароль?",0,687,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","раздвигая надвинувшиеся копья"],["v","Феб-Аполлон!",1,687,0,0],["v","Короткая пауза.",0,688,0,0],["sp","Корифей"],["v","Копья назад!",1,688,0,0],["v","<span class=\"ch\" data-ch=\"odissey\">Одиссея</span> освобождают.",0,689,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Где-нибудь здесь",0,690,0,1],["v","Спрятался вор…",0,690,0,0],["v","Сыщем его!",0,690,0,0],["sd","(Бежит.)"],["v","Пауза. Солдаты стоят в недоумении.",0,691,0,0],["sp","Первое полухорие"],["v","Оповестить?",0,691,0,0],["v","Дать им сигнал?",0,692,0,0],["sd","Пауза."],["sp","Второе полухорие"],["v","Ночь глубока,",0,692,0,0],["v","Сладок их сон, —",0,693,0,0],["v","Дайте вздремнуть",0,693,0,0],["v","Бедным друзьям!",0,694,0,0],["scene","Четвертый музыкальный антракт","s14",4,14],["sp","Первое полухорие"],["str","Строфа"],["v","Кто был этот эллин отважный?",0,694,0,0],["v","Хвалиться он будет, я знаю,",0,695,0,0],["v","Что стражу троянскую ночью",0,695,0,0],["v","Так ловко сумел обойти он.",0,696,0,0],["v","Ах, где же мы вора разыщем?",0,696,0,0],["v","Почем мы узнаем лихого?",0,697,0,0],["v","Мы хищника след потеряли.",0,697,0,0],["v","Стопой осторожной во мраке",0,698,0,0],["v","Хитрец миновал аванпосты.",0,698,0,0],["v","Кто ж этот смелый?",0,699,2,0],["v","Он — фессалиец,",0,699,2,0],["v","Или из локров<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,700,2,1],["v","Будет прибрежных?",0,700,2,0],["v","Может быть, бедный",0,701,2,0],["v","Островитянин?",0,701,2,0],["v","Где его город?",0,702,2,0],["v","Кто его боги?",0,702,2,0],["v","Парастат 1-й",0,703,0,0],["v","Без <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> тут не обошлося.",0,704,0,0],["v","Мне кажется, что тут его рука.",0,704,0,0],["sp","Первое полухорие"],["v","Его рука.",0,705,0,0],["v","Парастат 1-й",0,705,0,0],["sd","Пожалуй, так."],["sp","Первое полухорие"],["v","Смельчак какой!",0,706,0,0],["v","Парастат 1-й",0,707,0,0],["v","Какой смельчак?",1,707,0,0],["sp","Первое полухорие"],["v","Лаэрта сын…",0,707,0,0],["v","Парастат 1-й",0,708,0,0],["v","Он не смельчак,",0,708,4,0],["v","Он просто вор, обманщик он.",0,709,0,0],["sp","Второе полухорие"],["str","Антистрофа"],["v","Ты помнишь ли, воин, как в Трою<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,710,0,1],["v","С мольбой он однажды явился?..",0,711,0,0],["v","Заплаканы были ланиты.",0,712,0,0],["v","Лохмотьями платье висело,",0,713,0,0],["v","Отточенный меч прикрывая…",0,714,0,0],["v","Как нищий и беглый невольник,",0,715,0,0],["v","Всю голову грязью покрыл он,",0,716,0,0],["v","И царскому дому Атридов",0,717,0,0],["v","Проклятья он слал неустанно…",0,718,0,0],["v","Мы обманулись.",0,720,2,1],["v","Вора не надо",0,720,2,0],["v","Было нам слушать…",0,720,2,0],["v","Как <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>",0,721,2,0],["v","Мы не узнали?",0,721,2,0],["v","Как не убили?",0,722,2,0],["v","Трижды, коварный,",0,722,2,0],["v","Смерть заслужил он…",0,723,2,0],["v","Парастат 2-й",0,723,0,0],["v","Кто б ни был вор, но, признаюсь, мне страшно.",0,724,0,0],["v","Что скажет царь троянским сторожам?!",0,724,0,0],["sp","Второе полухорие"],["v","Что скажет царь?",0,725,0,0],["v","Парастат 2-й",0,725,0,0],["v","Он упрекнет.",1,725,0,0],["sp","Второе полухорие"],["v","Боишься ты?",0,725,0,0],["v","Парастат 2-й",0,726,0,0],["v","Бранить начнет…",0,726,4,0],["sp","Второе полухорие"],["v","За что бранить?",0,727,0,0],["v","Парастат 2-й",0,727,0,0],["v","Чего зевал,",1,727,0,0],["v","Зачем врагу войти давал?",0,728,0,0],["act","Действие пятое","a5","V"],["scene","Явление одиннадцатое","s15",5,15],["sp","Голос возницы"],["dir","за сценой"],["v","О, боги!",0,728,0,0],["v","Ой, лихо! Ой, тяжко!",0,729,0,0],["v","О, горькая доля!",0,729,0,0],["sp","Хор"],["dir","вполголоса"],["v","Чу… что это? Что это? Стоны?<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,730,0,1],["v","Тише, солдаты!",0,730,0,0],["v","Ради богов!",0,731,0,0],["v","Молча к земле припадем мы:",0,731,0,0],["v","Может быть, это шпион",0,732,0,0],["v","В сети троянцев попался…",0,732,0,0],["sd","(Прилегают к земле.)"],["sp","Голос возницы"],["v","О, горькая доля!",0,733,0,0],["v","О, горькая доля фракийцев!",0,733,0,0],["sp","Хор"],["dir","вполголоса"],["v","Там стонет союзник.",0,734,0,0],["sp","Голос возницы"],["v","О, горе! О, лютое горе!",0,734,0,0],["v","Я ранен и стражду, а ты,",0,735,0,0],["v","Владыка фракийцев,",0,735,0,0],["v","Зарезан… сгубила,",0,736,0,0],["v","Сгубила царя",0,736,0,0],["v","Проклятая Троя!",0,737,0,0],["sd","Показывается возница, мертвенно-бледный, растрепанный, окровавленный, без шапки, в разорванной рубахе, придерживая раненый живот."],["sp","Корифей"],["v","Союзник, чей ты, как тебя зовут?",0,737,0,0],["v","Тут так темно, что я тебя не вижу…",0,738,0,0],["sp","Возница"],["v","Люди, скажите мне,",0,738,0,0],["v","Где мне царя искать?",0,739,0,0],["v","Где тут ваш <span class=\"ch\" data-ch=\"gektor\">Гектор</span>",0,739,0,0],["v","В панцире сладко спит?",0,740,0,1],["v","Старший-то кто у вас?",0,740,0,0],["sd","(Пригибается от боли.)"],["v","Тяжко, ох, тяжко мне!",0,741,0,0],["v","Ох, что мы вынесли!",0,742,0,0],["sd","Молчание."],["v","Враг-то убил да и скрылся,",0,742,0,0],["v","А лютое горе осталось…",0,743,0,0],["v","Нашего горя не спрячешь…",0,744,0,0],["sd","Молчание."],["sd","(Возница садится на землю, склоняет голову и тихо стонет.)"],["sd","⟨Корифей⟩"],["v","Беда стряслась над их фракийским войском:",0,745,0,0],["v","Так, кажется, солдаты, он сказал?",0,745,0,0],["sp","Возница"],["dir","повышая голос, который скоро затем падает и переходит в шепот"],["v","Войска фракийского",0,746,0,0],["v","Нет, понимаешь ты?",0,747,0,0],["v","Предан обманщиком,",0,747,0,0],["v","Умер великий <span class=\"ch\" data-ch=\"res\">Рес</span>.",0,748,0,0],["sd","(Со слезами в голосе.)"],["v","…Боги, как тяжко мне,",0,749,0,0],["v","Рана болит моя,",0,750,0,1],["v","Так и горит внутри…",0,750,0,0],["v","Смерть приближается…",0,751,0,0],["v","…Царь наш, желанный наш!",0,752,0,0],["v","Как он спешил сюда,",0,752,0,0],["v","Выручить думал их;",0,753,0,0],["v","А за углом ждала",0,754,0,0],["v","Гибель бесславная…",0,755,0,0],["sp","Корифей"],["v","Сомнений нет. Союзники разбиты:",0,755,0,0],["v","Про гибель их он ясно говорит.",0,756,0,0],["sp","Возница"],["v","Что гибель! Тут была не гибель, люди,",0,757,0,0],["v","Тут был позор. Положим, умереть",0,757,0,0],["v","Не радостно и самой славной смертью…",0,758,0,0],["v","Ты не пожнешь похвал, ты не получишь",0,759,0,0],["v","Добычи сладостной, но все ж ты умер",0,760,0,1],["v","Прилично. Мы погибли бесполезно,",0,760,0,0],["v","Без смысла и без славы. Вот позор!",0,761,0,0],["v","Когда ваш царь нам собственной рукою",0,761,0,0],["v","Близ лагеря стоянку указал",0,762,0,0],["v","И передал пароль, сморенные походом,",0,762,0,0],["v","Мы на землю попадали: о да…",0,763,0,0],["v","Мы верили троянцам и не стали",0,764,0,0],["v","Оружие готовить, караул",0,764,0,0],["v","Особый ставить, даже в колесницах",0,765,0,0],["v","Стрекало неприправленным осталось…",0,765,0,0],["v","Наш бедный <span class=\"ch\" data-ch=\"res\">Рес</span> от <span class=\"ch\" data-ch=\"gektor\">Гектора</span> узнал,",0,766,0,0],["v","Что счастье улыбается троянцам,",0,767,0,0],["v","Что вы к судам врагов подобрались…",0,767,0,0],["v","Чего ж бояться было гостю Трои?",0,768,0,0],["v","Мы на землю попадали; и сон",0,768,0,0],["v","Мгновенно охватил фракийский лагерь.",0,769,0,0],["v","Но сон возницы крепок не бывает,",0,770,0,1],["v","И, прикорнув, я улежать не мог:",0,770,0,0],["v","Овса подсыпать надо было в ясли:",0,771,0,0],["v","\"Пусть, — думаю, — кобылы поедят,",0,772,0,0],["v","Наутро будет им работа\". Только вижу,",0,772,0,0],["v","Две тени будто бродят в темноте.",0,773,0,0],["v","Я подался навстречу им, и тотчас",0,774,0,0],["v","Они исчезли. Грозный окрик дав,",0,775,0,0],["v","Я запретил им подбираться к спящим:",0,775,0,0],["v","Что ж, воры, думаю, забрались от соседей!",0,776,0,0],["v","Довольно будет их разок пугнуть.",0,777,0,0],["v","Немножко обождал: вокруг ни звука,",0,777,0,0],["v","Ни тени — можно, значит, и вздремнуть…",0,778,0,0],["v","Тут ничего не помню — сон глубокий",0,779,0,0],["v","Сковал меня, и дивное виденье",0,780,0,1],["v","Очам предстало: будто я стою",0,780,0,0],["v","На царской колеснице перед <span class=\"ch\" data-ch=\"res\">Ресом</span>;",0,781,0,0],["v","Вдруг на хребты к кобылам взобрались",0,782,0,0],["v","Два волка, а хвосты их так и хлещут",0,782,0,0],["v","Испуганных по взмыленным бокам.",0,783,0,0],["v","И силятся стряхнуть их кобылицы,",0,784,0,0],["v","И ржанье гневное по воздуху несется…",0,785,0,0],["v","На хищников бичом вооружась,",0,785,0,0],["v","Я их согнать хочу и пробуждаюсь",0,786,0,0],["v","От ужаса… окрест все та же ночь.",0,787,0,0],["v","Приподнимаюсь, что же это? Стоны?",0,787,0,0],["v","Хрипенью умирающих внемлю.",0,788,0,0],["v","Я — к <span class=\"ch\" data-ch=\"res\">Ресу</span>: «Царь, проснись!», а он уж мертвый.",0,789,0,0],["v","Зарезан <span class=\"ch\" data-ch=\"res\">Рес</span>, — и оросил меня",0,790,0,1],["v","Ручей еще горячей царской крови…",0,790,0,0],["v","Я — на ноги, но только что копье",0,791,0,0],["v","Хотел схватить… ножом в живот, проклятый,",0,792,0,0],["v","Меня пырнул… О, боги, как мне больно!",0,793,0,0],["v","С какою силой нож вонзился в тело,",0,793,0,0],["v","И повернулся там отточенный клинок…",0,794,0,0],["v","И, кровью обливаясь, повалился",0,795,0,0],["v","Я на землю ничком: а между тем",0,796,0,0],["v","Злодеи, захвативши колесницу",0,796,0,0],["v","И лошадей, бежали, и куда?",0,797,0,0],["v","Ай, ай, ай, ай, о, боги, что за мука!",0,798,0,0],["v","Несчастный, и с земли не поднимусь.",0,799,0,0],["sd","(Делает усилие подняться; затем, помолчав и опираясь ладонью о землю, тихо.)"],["v","Весь этот ужас, люди, пережил я…",0,800,0,1],["v","Но кто убил,",0,800,0,0],["sd","(раздельно)"],["v","кто изувечил нас,",0,801,4,0],["v","Не знаю… Только вряд ли это греки!",0,802,0,0],["v","Мне чудится предатель из друзей…",0,803,0,0],["sp","Корифей"],["v","Возница злополучного фракийца,",0,804,0,0],["v","<span class=\"ch\" data-ch=\"res\">Рес</span> мог погибнуть только от врагов;",0,805,0,0],["sd","(указывая на входящего <span class=\"ch\" data-ch=\"gektor\">Гектора</span>)"],["v","Сам, посмотрев на <span class=\"ch\" data-ch=\"gektor\">Гектора</span>, не скажешь,",0,805,0,0],["v","Чтоб вашу скорбь делить он не хотел.",0,806,0,0],["v","Входит <span class=\"ch\" data-ch=\"gektor\">Гектор</span>, мрачный и гневный.",0,807,0,0],["scene","Явление двенадцатое","s16",5,16],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","строго, потом гневно"],["v","Где сторожа? Где те, кому я вверил",0,808,0,0],["v","Охрану лагеря и жизнь моих гостей?",0,809,0,0],["v","Шпионы были здесь, и вы не знали,",0,810,0,1],["v","Вы дали им у нас, на наш позор,",0,810,0,0],["v","Союзников троянских перерезать;",0,811,0,0],["v","Вы дали им бежать, чтобы потом",0,812,0,0],["v","Коварные над трусостью фригийской",0,812,0,0],["v","Натешились и вашего царя",0,813,0,0],["v","На кораблях аргосских осмеяли…",0,814,0,0],["v","Да разразит меня отец Зевес,",0,815,0,0],["v","Коли виновных не постигнет кара,",0,815,0,0],["v","И страшная… Сначала бичеванью",0,816,0,0],["v","Я вас предам, а после лютой казни.",0,817,0,0],["v","И обещал вам это Приамид;",0,817,0,0],["v","А если не исполнит, то считайте,",0,818,0,0],["v","Что <span class=\"ch\" data-ch=\"gektor\">Гектор</span> — самый жалкий человек.",0,819,0,0],["sp","Корифей"],["v","Грозный владыка,",0,820,0,1],["v","Если бы знал,",0,820,0,0],["v","Сколько я пережил",0,821,0,0],["v","Этою ночью",0,822,0,0],["v","Страшной тревоги.",0,822,0,0],["v","Помнишь ли, Гектор,",0,823,0,0],["v","Как я принес тебе",0,824,0,0],["v","Весть про огни?",0,825,0,0],["v","С этой минуты",0,825,0,0],["v","Целую ночь",0,826,0,0],["v","Я не садился,",0,827,0,0],["v","Глаз не сводил я…",0,827,0,0],["v","Царь, отложи свой гнев:",0,828,2,0],["v","Нет тут вины моей…",0,829,2,0],["v","Если ж когда,",0,830,2,1],["v","Словом ли, делом ли,",0,830,2,0],["v","Долг свой нарушу я,",0,831,2,0],["v","Гектор, живьем тогда",0,831,2,0],["v","В землю зарой меня!",0,832,2,0],["v","В землю живьем.",0,832,2,0],["sp","Возница"],["dir","приподнимаясь, с трудом"],["v","Угрозы сторожам, потоки слов!",0,833,0,0],["v","Послушай, царь, как варвар, ты умеешь",0,833,0,0],["v","Ложь хитрую сплетать, но ты забыл,",0,834,0,0],["v","Что я не грек, что я такой же варвар",0,835,0,0],["v","И знаю цену всем твоим речам.",0,835,0,0],["v","Царь <span class=\"ch\" data-ch=\"gektor\">Гектор</span>! Это ты зарезал <span class=\"ch\" data-ch=\"res\">Реса</span>…",0,836,0,0],["sd","Движение в хоре. <span class=\"ch\" data-ch=\"gektor\">Гектор</span> останавливает их рукою."],["v","Ты в эту ночь изранил и избил",0,836,0,0],["v","Своих друзей и речью не сумеешь",0,837,0,0],["v","Других запутать, а на что хитер!",0,837,0,0],["v","Настойчиво и долго зазывал ты",0,838,0,0],["v","Фракийцев, но не помощи ты ждал",0,838,0,0],["v","От <span class=\"ch\" data-ch=\"res\">Реса</span>, — ты хотел царя зарезать,",0,839,0,0],["v","Чтоб кобылиц его себе забрать.",0,840,0,1],["v","…Друзья пришли на зов и — перебиты…",0,840,0,0],["v","…Нет, Гектор, сам Парис, когда украл<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,841,0,0],["v","Жену у своего хозяина, позором",0,842,0,0],["v","Таким себя не запятнал, как ты,",0,842,0,0],["v","Когда союзников сгубил, гостей троянских.",0,843,0,0],["v","Свалить вину на грека так легко…",0,844,0,0],["v","Да за кордон-то эллин как пробрался?",0,845,0,0],["v","Как здесь он невидимкою прошел?",0,845,0,0],["v","Ведь между греками и нами был твой лагерь.",0,846,0,0],["v","И что фракийцы грекам? — между тем",0,847,0,0],["v","Враг мимо <span class=\"ch\" data-ch=\"gektor\">Гектора</span> проходит, из троянцев",0,847,0,0],["v","Не тронут ни один, и только нас,",0,848,0,0],["v","Едва прибывших, для него покуда",0,849,0,0],["v","Безвредных, нас, гостей, он не щадит.",0,850,0,1],["v","…О, сколько жертв израненных и скольких",0,851,0,0],["v","Луч солнца не разбудит!.. Но не грек",0,852,0,0],["v","Убийца наш. И как палатку <span class=\"ch\" data-ch=\"res\">Реса</span>",0,853,0,0],["v","Найти он мог во мраке? Наконец,",0,854,0,0],["v","Как мог узнать, что прибыли фракийцы?",0,855,0,0],["v","Все это, Гектор, выдумка и ложь!..",0,856,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","мрачно, с оттенком презрения в голосе"],["v","Царю троянскому союзники не диво:",0,857,0,0],["v","С тех пор как нас ахеец осадил,",0,858,0,0],["v","Я вижу их довольно, но упреков",0,859,0,0],["v","В предательстве не слышал. И не ты",0,860,0,1],["v","Начнешь их, жалкий конюх… Кобылицы!",0,860,0,0],["v","Нет, из-за них еще своих друзей",0,861,0,0],["v","Не резал <span class=\"ch\" data-ch=\"gektor\">Гектор</span>… <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> проклятый!",0,862,0,0],["v","Не обойдутся греки без него,",0,862,0,0],["v","Где нужен ум, проворство и отвага.",0,863,0,0],["v","А что ж Долон? Давно бы надо быть",0,864,0,0],["v","Ему обратно. И подумать жутко:",0,865,0,0],["v","Что, если <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> его накрыл?..",0,865,0,0],["sd","(Вздохнув.)"],["v","Тогда домой смельчак наш не вернется.",0,866,0,0],["sp","Возница"],["v","Каких ты Одиссеев тут нашел?",0,867,0,0],["v","Не враг, не враг убил нас, понимаешь?",0,867,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","И думай, что не враг: мне все равно.",0,868,0,0],["sp","Возница"],["dir","ослабевшим голосом"],["v","Так… это — смерть, прости меня, отчизна.",0,869,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","живо"],["v","О нет, не умирай, довольно жертв!",0,870,0,1],["sp","Возница"],["v","Куда ж я денусь здесь без господина?",0,870,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Все дам тебе — лекарства и приют.",0,871,0,0],["sp","Возница"],["v","Приют у царского злодея, у убийцы?!",0,872,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","сдерживаясь"],["v","Он — все свое! Бедняга, это бред…",0,873,0,0],["sp","Возница"],["dir","слабым голосом"],["v","Пусть наш злодей, кто б ни был он, погибнет…",0,874,0,0],["v","Ты или нет… про это знает бог.",0,875,0,0],["sd","(Лишается чувств.)"],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","слугам"],["v","Возьмите, слуги, этого больного",0,875,0,0],["v","И в дом мой отведите, и пускай",0,876,0,0],["v","Ни в чем ему не будет там отказа…",0,877,0,0],["sd","(Другим.)"],["v","А вы ступайте в город поживей,",0,878,0,0],["v","Скажите там Приаму и старшинам:",0,879,0,0],["v","Пусть мертвых с честью в Трое погребут,",0,880,0,1],["v","У большака, на первом повороте.",0,880,0,0],["v","Раненого уносят.",0,881,0,0],["act","Исход","a6",""],["scene","Явление тринадцатое","s17",6,17],["sd","В глубине сцены, на альтане появляется Муза, освещенная голубоватым светом, на коленях у нее лежит головой <span class=\"ch\" data-ch=\"res\">Рес</span>; бледное лицо, золотистые кудри, без шлема, в металлическим поясе сверх хитона и в окровавленном плаще."],["sp","Первое полухорие"],["v","Задернут блеск победный",0,882,0,0],["v","Печальным покрывалом…",0,883,0,0],["v","Что ж нам готовят боги?",0,884,0,0],["sp","Второе полухорие"],["v","Ай, ай!",0,885,2,0],["v","Постойте!",0,885,2,0],["v","Что это значит?",0,886,2,0],["v","Над нами божество — в его руках",0,887,0,0],["v","Останки только что убитого фракийца.",0,888,0,0],["v","Ох, страшно мне! Ох, страшно мне!",0,889,0,0],["sd","Все склоняются к земле, закрыв лица руками."],["sp","Муза"],["v","Не бойтесь, люди! Можете смотреть",0,890,0,1],["v","Свободно мне в лицо… Я — Пиерида.",0,890,0,0],["v","Всех девять нас; я — муза мудрецов,",0,891,0,0],["v","А это — сын мой, это — мой любимый,",0,891,0,0],["v","Убитый <span class=\"ch\" data-ch=\"odissey\">Одиссеем</span> бедный <span class=\"ch\" data-ch=\"res\">Рес</span>…",0,892,0,0],["v","Коварный грек поплатится за <span class=\"ch\" data-ch=\"res\">Реса</span>.",0,892,0,0],["str","Строфа"],["v","Бедное дитятко!",0,893,2,0],["v","Песнь погребальную",0,894,2,0],["v","Муза поет над тобой.",0,894,2,0],["v","Славы себе не добыл ты,",0,895,2,0],["v","Матери сердце разбил.",0,895,2,0],["v","Я ли, лаская, тебя не молила?",0,896,0,0],["v","Мало ль отец твой грозил?",0,897,2,0],["v","\"<span class=\"ch\" data-ch=\"res\">Рес</span>, не ходи!",0,897,4,0],["v","Горек твой дальний путь\".",0,898,2,0],["v","Нет, ты не слушал нас,",0,898,2,0],["v","Ты им помочь летел,",0,899,2,0],["v","Милое дитятко,",0,900,2,1],["v","Бедный мой <span class=\"ch\" data-ch=\"res\">Рес</span>.",0,900,2,0],["sp","Корифей"],["v","Чужой тебе я, Муза, человек,",0,901,0,0],["v","Но мне с тобою хочется заплакать…",0,902,0,0],["sp","Муза"],["str","Антистрофа"],["v","Сгибните, изверги!",0,903,2,0],["v","Сгибни, Ойнеев внук,",0,903,2,0],["v","Сгибни ты, царь <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>!",0,904,2,0],["v","Вы погубили коварно",0,905,2,0],["v","Славного сына богов!<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,906,2,0],["v","Проклята будь ты, спартанка Елена:",0,906,0,0],["v","В Трою тебя увлекла",0,907,2,0],["v","Жгучая страсть…",0,908,4,0],["v","Ведь за нее на бой",0,909,2,0],["v","Вышел и ты, мой <span class=\"ch\" data-ch=\"res\">Рес</span>!",0,910,2,1],["v","Из-за нее теперь",0,910,2,0],["v","Сколько домов пустых,",0,911,2,0],["v","Сколько сирот!",0,912,2,0],["sd","(Ласкает волосы <span class=\"ch\" data-ch=\"res\">Реса</span>.)"],["v","О, Фамирид, надменный нечестивец,",0,912,0,0],["v","В обитель мрачную ты уж давно сошел,",0,913,0,0],["v","А бедной Музе сердце все терзаешь…",0,914,0,0],["v","Да, если бы, гордыней ослеплен,",0,914,0,0],["v","Ты вызова тогда не бросил Музам,<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,915,0,0],["v","И мы бы не спешили на Пангей,",0,916,0,0],["v","Мне хоронить бы не пришлося сына,",0,916,0,0],["v","Я бы на свет его не родила.",0,917,0,0],["sd","(Вспоминает.)"],["v","Мы были на пути к Пангейским высям,",0,918,0,0],["v","И я поток сбиралась перейти,",0,918,0,0],["v","Когда волна меня в объятья бога,",0,919,0,0],["v","На ложе брачное к Стримону унесла.",0,920,0,1],["v","И Муза стала матерью героя…",0,921,0,0],["v","Как стыдно было мне тогда сестер.",0,922,0,0],["v","Тебя, мой бедный <span class=\"ch\" data-ch=\"res\">Рес</span>, в родные волны,",0,923,0,0],["v","К отцу прекрасному на лоно унесли;",0,924,0,0],["v","Не люди сына Музы воспитали:",0,925,0,0],["v","У вещих нимф, под говор светлых струй,",0,926,0,0],["v","Ты вырос, и могучий и прекрасный,",0,930,0,1],["v","Фракийцам царь и лучший из людей.",0,930,0,0],["v","Ты воевал со скифом, и спокойно",0,931,0,0],["v","Смотрела я на бранную игру.",0,932,0,0],["v","О, только бы не Троя и не греки!",0,933,0,0],["v","Но вот гонцами начал донимать",0,934,0,0],["v","Тебя то царь троянский, то вельможи…",0,935,0,0],["v","Богине жребий сына был открыт,",0,935,0,0],["v","Но воина жена не удержала.",0,936,0,0],["v","…Убийцы — Диомед и <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>,",0,937,0,0],["v","Движенье в хоре.",0,938,0,0],["v","Но обагренных кровью не виню я…",0,939,0,0],["v","Ты, ты — виной, Паллада, это ты",0,940,0,1],["v","К заснувшему ахейцев подослала…",0,940,0,0],["v","Мы ль, девять Муз, твой город не любили,",0,941,0,0],["v","Подолгу не гостили у тебя?",0,942,0,0],["v","Орфей, что таинства тебе преподал,<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,942,0,0],["v","Был <span class=\"ch\" data-ch=\"res\">Ресу</span> брат двоюродный; Мусей,",0,943,0,0],["v","Тот славный муж Афин твоих, богиня,",0,944,0,0],["v","Из смертных самый мудрый, разве он",0,945,0,0],["v","Не нами был воспитан и не Фебом?",0,945,0,0],["v","А что ты мне взамен теперь дала?",0,946,0,0],["v","Зарезанного сына бедной Музе",0,947,0,0],["v","Вернула, труп даешь похоронить?",0,947,0,0],["sd","(Склоняясь к сыну.)"],["v","О, милый <span class=\"ch\" data-ch=\"res\">Рес</span>, мне помощи не надо,",0,948,0,0],["v","Чтобы оплакать твой холодный прах…",0,949,0,0],["sp","Корифей"],["v","Выходит, Гектор, что не мы с тобою",0,950,0,1],["v","Убили <span class=\"ch\" data-ch=\"res\">Реса</span>; конюх был не прав.",0,950,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["v","Да, <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> убил его; и раньше,",0,951,0,0],["v","Без всякого оракула, ваш царь",0,952,0,0],["v","Указывал на козни <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>.",0,952,0,0],["v","Ну что ж? Фракийца я, конечно, звал…",0,953,0,0],["v","Когда ж и обращаться было к другу,",0,954,0,0],["v","Как не теперь, когда враги стеснили?",0,954,0,0],["v","<span class=\"ch\" data-ch=\"res\">Рес</span> понимал меня и разделить",0,955,0,0],["v","Мои труды привел сюда дружину.",0,956,0,0],["v","Иначе он и поступить не мог,",0,956,0,0],["v","Как добрый друг и благородный воин.",0,957,0,0],["v","Мне жаль погибшего, и я велю",0,958,0,0],["v","Ему гробницу пышную поставить,",0,958,0,0],["v","Одежды драгоценные спалю",0,959,0,0],["v","Я на костре его.",0,960,0,1],["sd","(Обращаясь к телу <span class=\"ch\" data-ch=\"res\">Реса</span>.)"],["v","Прости, товарищ,",0,960,4,0],["v","Придя как гость, как нищий ты ушел…",0,961,0,0],["sp","Муза"],["v","Царь, сын мой не сойдет в долину смерти.",0,962,0,0],["v","Нет, я подземную царицу умолю,",0,962,0,0],["v","Скажу ей: \"Дочь Деметры плодоносной,",0,963,0,0],["v","Отдай мне душу <span class=\"ch\" data-ch=\"res\">Реса</span>\", — и почтит",0,964,0,0],["v","Друзей Орфея адская богиня…",0,965,0,0],["v","…Увы, среди богов ему не быть",0,965,0,0],["v","И в сонме жен бессмертных жадным оком",0,966,0,0],["v","Погибшему родимой не искать.",0,967,0,0],["sd","(Пристально глядит на <span class=\"ch\" data-ch=\"res\">Реса</span>, оправляя ему волосы, с глубокой грустью в голосе.)"],["v","Я <span class=\"ch\" data-ch=\"res\">Реса</span> тоже больше не увижу!",0,967,0,0],["v","В глубоких, мрачных впадинах земли",0,968,0,0],["v","На золотом Пангее он возляжет",0,969,0,0],["v","Властителем несметных рудников:",0,970,0,1],["v","Незрим и общей смерти недоступен,",0,970,0,0],["v","Он будет волю Вакха из пещер",0,971,0,0],["v","Передавать благочестивым мистам…",0,971,0,0],["v","Дай хоть теперь тебя оплакать, <span class=\"ch\" data-ch=\"res\">Рес</span>.",0,972,0,0],["sd","(Поднимает голову, в экстазе.)"],["v","Богиня моря, вещая Фетида,",0,973,0,0],["v","Мой горький жребий выпадет и ей…",0,973,0,0],["v","Она здесь тоже потеряет сына.",0,974,0,0],["v","Едва тебя мы мелодичным гимном",0,975,0,0],["v","Прославим и оплачем, бедный <span class=\"ch\" data-ch=\"res\">Рес</span>,",0,975,0,0],["v","Как очередь наступит Ахиллесу:",0,976,0,0],["v","На гибель царь могучий осужден.",0,976,0,0],["v","Стрелу в колчане Локсий сам наметит,",0,977,0,0],["v","Ее враждой бессмертной окрылит…",0,978,0,0],["v","И не спасет его завистливая дева,",0,978,0,0],["v","Что слезы мне теперь велела лить…",0,979,0,0],["v","…О кара смертных женщин, материнство!",0,980,0,1],["v","Рожать детей, чтоб после хоронить…",0,981,0,0],["sd","Красная заря охватывает горизонт. Виденье исчезает."],["sp","Корифей"],["v","Мать похоронит бедного фракийца,",0,982,0,0],["v","А нас, троянский царь, работа ждет.",0,983,0,0],["v","Смотри: на небе день, и враг не дремлет.",0,984,0,0],["sp","<span class=\"ch\" data-ch=\"gektor\">Гектор</span>"],["dir","к хору"],["v","Ступай к союзникам и прикажи,",0,985,0,0],["v","Чтоб торопились запрягать, а факел",0,986,0,0],["v","Пусть наготове держит каждый воин.",0,987,0,0],["v","Сигнал им даст тирренская труба!",0,988,0,0],["v","Сейчас мы переходим загражденья,",0,989,0,0],["v","Мы пламенем наполним вражий стан,",0,990,0,1],["v","Суда зажжем, и зарево пожара,",0,991,0,0],["v","Мешаясь с блеском утра, возвестит,",0,992,0,0],["v","Что новый день восходит, избавленья!",0,993,0,0],["sd","(Уходит.)"],["sp","Хор"],["dir","уходит под марш"],["v","Повинуйтесь, солдаты, царю,",0,994,0,0],["v","И пойдем исполнять его волю!",0,995,0,0],["v","Что велел он, объявим друзьям…",0,996,0,0],["v","Как узнаешь, что нынче случится?",0,997,0,0],["v","Может быть, и для Трои теперь",0,998,0,0],["v","Изготовили боги победу.",0,999,0,0],["sd","После короткой паузы за сценой слышится звук трубы."],["h1","Комментарий","comm"],["p","Содержание этой трагедии заимствовано из последних стихов VIII и X кн. «Илиады». Здесь троянцы, после решительного натиска на ахейцев, остаются ночевать в поле за пределами городской крепости. На следующий день Гектор рассчитывает покончить с пришельцами."],["p","Между тем старейшины обоих войск приходят к мысли о необходимости заслать разведчиков во вражеский стан. Со стороны ахейцев вызывается Диомед, который берет себе в товарищи Одиссея, со стороны троянцев — Долон, заручившись обещанием Гектора подарить ему в случае победы колесницу и волшебных коней Ахилла. Однако ахейцам удается перехватить в поле Долона, узнать от него размещение троянцев и, в частности, получить известие о прибытии накануне в троянский лагерь фракийского царя Реса, владеющего колесницей и белыми конями необыкновенной красоты. Прикончив Долона и проникнув в расположение троянских союзников, Диомед убивает 12 спящих фракийцев (13-м становится сам Рес), а Одиссей выводит из стана лошадей, после чего разведчики с триумфом возвращаются в ахейский лагерь."],["p","Эта сюжетная схема потерпела, однако, в трагедии существенные видоизменения, и причем далеко не к лучшему. Во-первых, по «Илиаде», лагерь греков погружен в глубокий сон, а в лагере троянцев пылают десятки костров, чтобы в него не мог проникнуть никто из врагов. В трагедии — картина обратная: троянская стража обеспокоена множеством огней в ахейском стане, так что Гектор подозревает даже, не собираются ли греки покинуть этой ночью троянский берег; напротив, в лагере троянцев господствует ночной мрак, и зрителям приходится прилагать величайшие усилия, чтобы представить себе, как действие, происходящее на залитой солнцем орхестре, на самом деле развертывается в глубокой тьме. Во-вторых, в трагедию внесен мотив недовольства со стороны Гектора поздним появлением Реса: он считает, что фракийский царь прибыл только для того, чтобы воспользоваться плодами не им добытой победы. Впрочем, спор Гектора с Ресом дальнейшего развития не получает, хотя их столкновение могло бы составить зерно трагического конфликта, которого в трагедии, по существу, нет. К тому же Рес ведет себя крайне заносчиво и готов сразиться один на один с самим Ахиллом или хотя бы с Аяксом и Диомедом. Не сомневаясь в победе, он готов чуть ли не в тот же день перенести войну в Элладу. Затем, пробравшиеся в троянский лагерь Диомед и Одиссей считают почему-то своей первоочередной задачей убийство Гектора, которого им у Гомера никто не поручал, и только не найдя вождя троянцев в его шатре, по совету Афины переключают свое внимание на Реса. Сама же Афина берет на себя успокоительный диалог с Парисом, прослышавшим что-то о появлении в лагере вражеских лазутчиков, причем для большей убедительности принимает на время вид его всегдашней покровительницы Киприды. Наконец, после убийства Реса Одиссей, которому следовало бы во всю прыть гнать в лагерь захваченных лошадей, появляется зачем-то среди троянских дозорных, притворяясь одним из их союзников."],["p","Вызывают сомнение и некоторые композиционные особенности трагедии. Прежде всего, в ней нет ни пролога, ни парода в собственном смысле слова: в самом начале пьесы хор находится на орхестре и короткой вступительной песней будит Гектора. Если не предположить, что в рукописи, послужившей образцом для тех, в которых сохранился «Рес», был утерян лист, содержавший экспозиционный пролог, то надо признать начало трагедии образцом либо очень смелого художественного эксперимента, либо драматургической неопытности. Затем, вестник в греческой трагедии, даже сообщающий о самых мрачных событиях, сам в них обычно участия не принимает; в «Ресе» рассказ о нападении на фракийцев вложен в уста тяжело раненного возницы Реса, который не только повествует о самом факте убийства, но и о привидевшемся ему сне, и вдобавок выдвигает свою версию: Реса прикончили не проникшие в лагерь греки, а сами троянцы, в первую очередь — Гектор. Наконец, Муза, мать Реса, играющая роль deus ex machina, не столько предрекает последующие события, сколько описывает предысторию похода сына под Трою, повествуя в эпилоге о том, для чего самое подходящее место — в прологе."],["p","Все эти соображения — и содержательные и формальные — заставили некоторых ученых уже в античности сомневаться применительно к «Ресу» в авторстве Еврипида; эту точку зрения разделяют и многие современные исследователи, считая, что дошедший до нас текст «Реса» — творчество неизвестного поэта первой половины IV в. до н. э., каким-то образом заменившее в собрании сочинений Еврипида его подлинный текст. В этом случае надо признать большой удачей для исследователей, что им в руки попал единственный полный экземпляр афинской трагедии IV в., о которой мы в остальном информированы очень плохо."],["p","Что касается перевода Инн. Анненского, то он является одним из наименее удачных, предвещая недостатки, которые будут характерны и для последующих его переводов Еврипида: игнорируется в ряде случаев метрическое своеобразие оригинала (так, анапесты в ст. 1 — 10, 17 — 22, 34 — 40, 379 — 398 заменены либо ямбами, либо дактилями), нет попытки приблизиться к метрической структуре хоровых партий, обильно используются модернизмы («шпион», «кордон», «лозунг» и т. п.)."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"]],"n":{"k1":["Ст. 28. Сына Панфоева…","У Панфоя, троянского жреца Аполлона, было два сына, отличавшихся храбростью, — Евфорб и Пулидамант. Более известен первый из них, убитый впоследствии Патроклом."],"k2":["Ст. 29. Славный Европы сын","обычное смешение Сарпедона, сына Европы и Зевса, с ликийским царем Сарпедоном, сыном Зевса от Лаодамии."],"k3":["Ст. 85. Эней","троянский вождь, сын Анхиса и богини Афродиты."],"k4":["Ст. 158. …имя оправдать…","Имя Долон Гектор производит от греческого dolos — «хитрость»."],"k5":["Ст. 166. Что в царстве?","Популярная в греческой трагедии мысль о том, что царская власть — обуза для человека."],"k6":["Ст. 168. Жену знатней себя…","столь же распространенное высказывание, что в неравном браке нет счастья."],"k7":["Ст. 182. Пелидовы кони","Ксанф и Балий, порожденье бога ветра Зефира и гарпии Подарги. Впрочем, о желании самого Гектора завладеть конями Ахилла у Гомера ничего нет. В остальном перевод ст. 182 сл. — один из примеров переводческого многословия Анненского. Пяти стихам в переводе: «Чего хочу?.. Пелеевых коней» — в оригинале соответствуют две строчки: «Коней Ахилла. Тому причитается достойная награда, кто ставит свою жизнь на кон божества»."],"k8":["Ст. 187. Сам владыка моря","бог Посейдон якобы подарил коней отцу Ахилла Пелею. За дочерью их отдал брат Зевеса — туманный стих: мать Ахилла Фетида была дочерью морского старца Нерея, который, однако, не мог дать ей в приданое чужих коней. В оригинале этот стих поддержки не находит."],"k9":["Ст. 208. …надену волчью шкуру…","Эта деталь есть и у Гомера, но там Долон не собирается бегать на четвереньках."],"k10":["Ст. 222. Тидид","Диомед, сын Тидея."],"k11":["Ст. 224. Стены воздвигнувший Трои","Аполлон. См. «Троянки», ст. 4 — 7."],"k12":["Ст. 258. Спартанец","Менелай; другой Атрид — Агамемнон, который приходился Елене не зятем, а деверем."],"k13":["Ст. 311. Пелътасты","в историческое время — зависимое население во Фракии, служившее в качестве легковооруженных."],"k14":["Ст. 342. Неизбежная дева","в оригинале «Адрастея», один из эпитетов богини возмездия Немесиды."],"k15":["Ст. 404. Ты, варвар сам…","Оценка с точки зрения греков, которые называли варварами всех, говоривших не по-гречески."],"k16":["Ст. 408. Пашей","гористая местность на восток от устья Стримона."],"k17":["Ст. 426. Скифы.","Гомеровский эпос о скифах ничего не знает. Их участие в военнополитических отношениях — реалии V — IV вв."],"k18":["Ст. 436. Чрез пролив","Геллеспонт."],"k19":["Ст. 453","Примечание Анненского: «В переводе не соблюдена в этом случае антистрофичность»."],"k20":["Ст. 500. Грек ни один…","По мифологической хронологии, Одиссей похитил из храма Афины ее статую и являлся на разведку в Трою под видом нищего (ср. «Гекуба», ст. 239-250) значительно позже, уже после гибели Гектора."],"k21":["Ст. 508. Фимбрейский Аполлон","храм Аполлона в городе Фимбре, на юго-восток от Трои."],"k22":["Ст. 509. Наслище","неологизм Анненского, по смыслу оригинала — «напасть», «гибель». В оригинале сказано: «Боремся мы с губительным злом»."],"k23":["Ст. 530. Седъмица скитальцев","созвездие Плеяд, появляющееся весной на небе незадолго до восхода солнца; орел лучезарный — созвездие в северной части неба. Перестановка частей текста (видная по нумерации стихов) и распределение реплик между полухориями и начальниками полухорий (парастатами) принадлежит Анненскому и не совпадает с традиционным."],"k24":["Ст. 540 — 543. Киликийцы, мисийцы, ликийцы","жители стран, соседних с Троей."],"k25":["Ст. 551. …О сыне тоскуя…","Речь идет об афинской царевне Прокне, которая из мести мужу убила сына и была превращена в соловья; его песни напоминают о вечной тоске Прокны."],"k26":["Ст. 597. Александр","другое имя Париса."],"k27":["Ст. 648. За правый суд","то есть за победу, присужденную ей Парисом в споре трех богинь."],"k28":["Ст. 700. Локры","обитатели одной из трех областей Средней Греции, носившей название Локриды. Ее побережье омывалось Евбейским проливом."],"k29":["Ст. 710","См. примеч. к ст. 500. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 500. Грек ни один….</b> По мифологической хронологии, Одиссей похитил из храма Афины ее статую и являлся на разведку в Трою под видом нищего (ср. «Гекуба», ст. 239-250) значительно позже, уже после гибели Гектора.</span><!--/xn-->"],"k30":["Ст. 729 сл. Чу… что это?","Еще один пример многословия переводчика. Шести стихам перевода в оригинале соответствует междометие «О, о!» и фраза: «Стоять всем молча! Кажется, кто-то идет к нам в сеть!»"],"k31":["Ст. 841. …Парис, когда украл жену…","Принятый по всем обычаям гостеприимства в доме Менелая, Парис отплатил ему тем, что соблазнил и похитил Елену."],"k32":["Ст. 906. Ойнеев внук","Диомед."],"k33":["Ст. 915. Фамирид","фракийский певец, посмевший тягаться с Музами. Из-за этого они отправились на Пангей, и по дороге будущая мать Реса, по ее словам, стала жертвой насилия речного бога Стримона."],"k34":["Ст. 943. Орфей","сын другой Музы, Каллиопы."]},"mainEnd":1627,"c":[{"id":"gektor","name":"Гектор","role":"Сын Приама, вождь троянцев","intro":"Полководец, готовый ночью напасть на ахейцев.","arc":"Гектор в «Ресе» горяч и самоуверен: он хочет немедленно атаковать, посылает лазутчика Долона и встречает союзника Реса упрёками. Наутро он узнаёт, что Рес убит, и возница обвиняет в этом его самого.","st":[{"i":144,"p":9,"l":"Действие первое · явление первое","t":"Тревога","d":"Разбуженный стражей, хочет сразу атаковать ахейцев.","c":"","k":false},{"i":236,"p":15,"l":"Действие первое · явление второе","t":"Совет Энея","d":"Эней убеждает его сначала разведать обстановку.","c":"","k":false},{"i":314,"p":19,"l":"Действие первое · явление третье","t":"Долон","d":"Посылает Долона лазутчиком к ахейцам.","c":"","k":true},{"i":793,"p":49,"l":"Действие третье · явление шестое","t":"Встреча с Ресом","d":"Упрекает союзника в опоздании.","c":"","k":false},{"i":1171,"p":72,"l":"Действие четвертое · Четвертый музыкальный антракт","t":"Обвинение","d":"Возница обвиняет его в убийстве Реса; Гектор отвергает это.","c":"","k":false}],"gen":"Гектор"},{"id":"res","name":"Рес","role":"Фракийский царь","intro":"Молодой союзник троянцев, прибывший на десятом году войны.","arc":"Рес блестящ и хвастлив: он обещает за один день решить войну — и погибает в первую же ночь.","st":[{"i":793,"p":49,"l":"Действие третье · явление шестое","t":"Прибытие","d":"Оправдывается и обещает решить войну за один день.","c":"","k":true},{"i":1171,"p":72,"l":"Действие четвертое · Четвертый музыкальный антракт","t":"Гибель","d":"Возница рассказывает, как Реса убили во сне.","c":"","k":false},{"i":1318,"p":81,"l":"Действие пятое · явление одиннадцатое","t":"Плач Музы","d":"Муза-мать оплакивает его.","c":"","k":false}]},{"id":"odissey","name":"Одиссей","role":"Царь Итаки","intro":"Ахейский лазутчик.","arc":"Одиссей с Диомедом проникают в троянский лагерь и с помощью Афины убивают Реса.","st":[{"i":921,"p":57,"l":"Действие четвертое · явление седьмое","t":"Вылазка","d":"С Диомедом убивает Долона и по совету Афины идёт к Ресу.","c":"","k":true},{"i":1029,"p":63,"l":"Действие четвертое · явление девятое","t":"Ускользает","d":"Узнав пароль, уходит от стражи.","c":"","k":false}]}]};
